import React from 'react';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';

const ProfileCompletionCard = ({ completionData, onCompleteSection }) => {
  const { percentage, completedSections, missingSections } = completionData;

  const getCompletionColor = (percentage) => {
    if (percentage < 30) return 'text-destructive';
    if (percentage < 70) return 'text-warning';
    return 'text-success';
  };

  const getProgressBarColor = (percentage) => {
    if (percentage < 30) return 'bg-destructive';
    if (percentage < 70) return 'bg-warning';
    return 'bg-success';
  };

  const sectionIcons = {
    'Personal Details': 'User',
    'Profile Picture': 'Camera',
    'Contact Information': 'Phone',
    'Bio': 'FileText',
    'Preferences': 'Settings',
    'Security': 'Shield'
  };

  return (
    <div className="bg-gradient-to-br from-primary/5 to-accent/5 border border-border rounded-lg p-6 mb-8">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center space-x-3">
          <div className="w-10 h-10 bg-primary/10 rounded-lg flex items-center justify-center">
            <Icon name="Target" size={20} className="text-primary" />
          </div>
          <div>
            <h3 className="font-heading font-semibold text-lg text-foreground">
              Profile Completion
            </h3>
            <p className="font-caption text-sm text-muted-foreground">
              Complete your profile to unlock all features
            </p>
          </div>
        </div>
        <div className="text-right">
          <div className={`font-heading font-bold text-2xl ${getCompletionColor(percentage)}`}>
            {percentage}%
          </div>
          <p className="font-caption text-xs text-muted-foreground">Complete</p>
        </div>
      </div>
      {/* Progress Bar */}
      <div className="mb-6">
        <div className="w-full bg-muted rounded-full h-3">
          <div
            className={`h-3 rounded-full transition-all duration-500 ${getProgressBarColor(percentage)}`}
            style={{ width: `${percentage}%` }}
          />
        </div>
      </div>
      {/* Completed Sections */}
      {completedSections?.length > 0 && (
        <div className="mb-4">
          <h4 className="font-body font-medium text-sm text-foreground mb-2 flex items-center">
            <Icon name="CheckCircle" size={16} className="text-success mr-2" />
            Completed ({completedSections?.length})
          </h4>
          <div className="flex flex-wrap gap-2">
            {completedSections?.map((section) => (
              <div
                key={section}
                className="flex items-center space-x-2 px-3 py-1 bg-success/10 text-success rounded-full"
              >
                <Icon name={sectionIcons?.[section] || 'Check'} size={14} />
                <span className="font-caption text-xs">{section}</span>
              </div>
            ))}
          </div>
        </div>
      )}
      {/* Missing Sections */}
      {missingSections?.length > 0 && (
        <div className="mb-4">
          <h4 className="font-body font-medium text-sm text-foreground mb-2 flex items-center">
            <Icon name="AlertCircle" size={16} className="text-warning mr-2" />
            Needs Attention ({missingSections?.length})
          </h4>
          <div className="space-y-2">
            {missingSections?.map((section) => (
              <div
                key={section?.name}
                className="flex items-center justify-between p-3 bg-warning/5 border border-warning/20 rounded-lg"
              >
                <div className="flex items-center space-x-3">
                  <Icon name={sectionIcons?.[section?.name] || 'AlertCircle'} size={16} className="text-warning" />
                  <div>
                    <p className="font-body font-medium text-sm text-foreground">
                      {section?.name}
                    </p>
                    <p className="font-caption text-xs text-muted-foreground">
                      {section?.description}
                    </p>
                  </div>
                </div>
                <Button
                  variant="outline"
                  size="sm"
                  iconName="ArrowRight"
                  iconPosition="right"
                  onClick={() => onCompleteSection(section?.action)}
                >
                  Complete
                </Button>
              </div>
            ))}
          </div>
        </div>
      )}
      {/* Completion Benefits */}
      {percentage < 100 && (
        <div className="bg-card border border-border rounded-lg p-4">
          <h4 className="font-body font-medium text-sm text-foreground mb-2 flex items-center">
            <Icon name="Gift" size={16} className="text-primary mr-2" />
            Complete Your Profile to Unlock:
          </h4>
          <ul className="space-y-1">
            <li className="flex items-center space-x-2 font-caption text-xs text-muted-foreground">
              <Icon name="Check" size={12} className="text-success" />
              <span>Enhanced member directory visibility</span>
            </li>
            <li className="flex items-center space-x-2 font-caption text-xs text-muted-foreground">
              <Icon name="Check" size={12} className="text-success" />
              <span>Personalized event recommendations</span>
            </li>
            <li className="flex items-center space-x-2 font-caption text-xs text-muted-foreground">
              <Icon name="Check" size={12} className="text-success" />
              <span>Priority access to exclusive content</span>
            </li>
            <li className="flex items-center space-x-2 font-caption text-xs text-muted-foreground">
              <Icon name="Check" size={12} className="text-success" />
              <span>Better networking opportunities</span>
            </li>
          </ul>
        </div>
      )}
      {/* Completion Celebration */}
      {percentage === 100 && (
        <div className="bg-success/10 border border-success/20 rounded-lg p-4 text-center">
          <Icon name="Trophy" size={32} className="text-success mx-auto mb-2" />
          <h4 className="font-heading font-semibold text-lg text-success mb-1">
            Profile Complete!
          </h4>
          <p className="font-caption text-sm text-muted-foreground">
            You've unlocked all profile features and benefits. Great job!
          </p>
        </div>
      )}
    </div>
  );
};

export default ProfileCompletionCard;