import React, { useState } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import Icon from '../AppIcon';
import Image from '../AppImage';
import Button from './Button';

const AuthenticatedHeader = ({ user = { name: 'John Doe', avatar: '/assets/images/avatar.jpg', role: 'member' } }) => {
  const [isProfileMenuOpen, setIsProfileMenuOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const location = useLocation();
  const navigate = useNavigate();

  const navigationItems = [
    { label: 'Dashboard', path: '/member-dashboard', icon: 'LayoutDashboard' },
    { label: 'Profile', path: '/profile-management', icon: 'User' },
  ];

  const adminItems = user?.role === 'admin' ? [
    { label: 'Admin Panel', path: '/admin-panel', icon: 'Settings' },
  ] : [];

  const allNavigationItems = [...navigationItems, ...adminItems];

  const isActivePath = (path) => location?.pathname === path;

  const handleLogout = () => {
    // Handle logout logic here
    navigate('/user-login');
  };

  const toggleProfileMenu = () => {
    setIsProfileMenuOpen(!isProfileMenuOpen);
  };

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  return (
    <header className="fixed top-0 left-0 right-0 z-50 bg-card border-b border-border shadow-card">
      <div className="max-w-7xl mx-auto">
        <div className="flex items-center justify-between h-16 px-4 lg:px-6">
          {/* Logo */}
          <Link to="/admin-panel" className="flex items-center space-x-3 hover:opacity-80 transition-smooth">
            <div className="w-10 h-10 bg-primary rounded-lg flex items-center justify-center">
              <svg
                viewBox="0 0 24 24"
                className="w-6 h-6 text-primary-foreground"
                fill="currentColor"
              >
                <path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5" />
              </svg>
            </div>
            <div className="hidden sm:block">
              <h1 className="font-heading font-bold text-xl text-foreground">
                GS Des Parents
              </h1>
              <p className="font-caption text-xs text-muted-foreground -mt-1">
                Admin  Portal
              </p>
            </div>
          </Link>

          {/* Desktop Navigation */}
          <nav className="hidden md:flex items-center space-x-6">
            {allNavigationItems?.map((item) => (
              <Link
                key={item?.path}
                to={item?.path}
                className={`flex items-center space-x-2 px-3 py-2 rounded-md font-body font-medium transition-smooth hover:bg-muted ${
                  isActivePath(item?.path)
                    ? 'text-primary bg-muted' :'text-foreground hover:text-primary'
                }`}
              >
                <Icon name={item?.icon} size={18} />
                <span>{item?.label}</span>
              </Link>
            ))}
          </nav>

          {/* Desktop Profile Menu */}
          <div className="hidden md:flex items-center space-x-4">
            <div className="relative">
              <button
                onClick={toggleProfileMenu}
                className="flex items-center space-x-3 px-3 py-2 rounded-md hover:bg-muted transition-smooth"
                aria-label="Profile menu"
              >
                <Image
                  src={user?.avatar}
                  alt={user?.name}
                  className="w-8 h-8 rounded-full object-cover"
                />
                <div className="text-left">
                  <p className="font-body font-medium text-sm text-foreground">{user?.name}</p>
                  <p className="font-caption text-xs text-muted-foreground capitalize">{user?.role}</p>
                </div>
                <Icon name="ChevronDown" size={16} className="text-muted-foreground" />
              </button>

              {/* Profile Dropdown */}
              {isProfileMenuOpen && (
                <div className="absolute right-0 top-full mt-2 w-48 bg-popover border border-border rounded-md shadow-elevated animate-fade-in">
                  <div className="py-2">
                    <Link
                      to="/profile-management"
                      onClick={() => setIsProfileMenuOpen(false)}
                      className="flex items-center space-x-2 px-4 py-2 text-sm font-body text-popover-foreground hover:bg-muted transition-smooth"
                    >
                      <Icon name="User" size={16} />
                      <span>My Profile</span>
                    </Link>

                    <button
                      onClick={() => {
                        setIsProfileMenuOpen(false);
                        handleLogout();
                      }}
                      className="flex items-center space-x-2 w-full px-4 py-2 text-sm font-body text-destructive hover:bg-muted transition-smooth"
                    >
                      <Icon name="LogOut" size={16} />
                      <span>Sign Out</span>
                    </button>
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Mobile Menu Button */}
          <button
            onClick={toggleMobileMenu}
            className="md:hidden p-2 rounded-md text-foreground hover:bg-muted transition-smooth"
            aria-label="Toggle mobile menu"
          >
            <Icon name={isMobileMenuOpen ? 'X' : 'Menu'} size={24} />
          </button>
        </div>

        {/* Mobile Menu */}
        {isMobileMenuOpen && (
          <div className="md:hidden bg-card border-t border-border animate-slide-in">
            <nav className="px-4 py-4 space-y-2">
              {/* User Info */}
              <div className="flex items-center space-x-3 px-3 py-3 bg-muted rounded-md mb-4">
                <Image
                  src={user?.avatar}
                  alt={user?.name}
                  className="w-10 h-10 rounded-full object-cover"
                />
                <div>
                  <p className="font-body font-medium text-sm text-foreground">{user?.name}</p>
                  <p className="font-caption text-xs text-muted-foreground capitalize">{user?.role}</p>
                </div>
              </div>

              {/* Navigation Items */}
              {allNavigationItems?.map((item) => (
                <Link
                  key={item?.path}
                  to={item?.path}
                  onClick={() => setIsMobileMenuOpen(false)}
                  className={`flex items-center space-x-3 px-3 py-3 rounded-md font-body font-medium transition-smooth ${
                    isActivePath(item?.path)
                      ? 'text-primary bg-muted' :'text-foreground hover:bg-muted hover:text-primary'
                  }`}
                >
                  <Icon name={item?.icon} size={20} />
                  <span>{item?.label}</span>
                </Link>
              ))}
              
              <div className="pt-4 border-t border-border space-y-2">
                <Button
                  variant="destructive"
                  fullWidth
                  className="font-body justify-start"
                  onClick={() => {
                    setIsMobileMenuOpen(false);
                    handleLogout();
                  }}
                >
                  <Icon name="LogOut" size={18} className="mr-2" />
                  Sign Out
                </Button>
              </div>
            </nav>
          </div>
        )}
      </div>
      {/* Click outside to close profile menu */}
      {isProfileMenuOpen && (
        <div
          className="fixed inset-0 z-40"
          onClick={() => setIsProfileMenuOpen(false)}
        />
      )}
    </header>
  );
};

export default AuthenticatedHeader;