import Footer from "../../components/ui/Footer";
import React, { useState } from "react";
import { Helmet } from "react-helmet";
import PublicHeader from "../../components/ui/PublicHeader";

const CourseCatalog = () => {
  const [activeTab, setActiveTab] = useState("all");
  const [expandedCourse, setExpandedCourse] = useState(null);

  const courses = {
    "For Trades": {
      L3: {
        title: "Trade Skills Fundamentals",
        description:
          "Introduction to essential trade skills and safety protocols",
        modules: [
          "Basic Tool Identification and Usage",
          "Workshop Safety Procedures",
          "Materials and Measurement",
          "Introduction to Blueprint Reading",
        ],
        duration: "6 months",
        certification: "Trade Skills Foundation Certificate",
      },
      L4: {
        title: "Specialized Trade Techniques",
        description: "Advanced techniques in specialized trade areas",
        modules: [
          "Advanced Material Applications",
          "Specialized Equipment Operation",
          "Trade Mathematics",
          "Quality Control Procedures",
        ],
        duration: "8 months",
        certification: "Advanced Trade Operations Certificate",
      },
      L5: {
        title: "Trade Management and Supervision",
        description: "Leadership and management skills for trade professionals",
        modules: [
          "Project Management for Trades",
          "Workforce Supervision",
          "Advanced Safety Compliance",
          "Business Operations for Trade Contractors",
        ],
        duration: "12 months",
        certification: "Trade Management Diploma",
      },
    },
    "Software Development": {
      L3: {
        title: "Programming Fundamentals",
        description: "Introduction to core programming concepts and techniques",
        modules: [
          "Introduction to Programming Logic",
          "Basic Web Technologies (HTML/CSS)",
          "Fundamentals of JavaScript",
          "Version Control with Git",
        ],
        duration: "6 months",
        certification: "Programming Essentials Certificate",
      },
      L4: {
        title: "Software Application Development",
        description: "Building functional software applications",
        modules: [
          "Object-Oriented Programming",
          "Database Design and SQL",
          "API Development",
          "Software Testing Methodologies",
        ],
        duration: "8 months",
        certification: "Application Developer Certificate",
      },
      L5: {
        title: "Advanced Software Engineering",
        description: "Enterprise-level software development practices",
        modules: [
          "Software Architecture Patterns",
          "DevOps and CI/CD Pipelines",
          "Cloud Computing Services",
          "Agile Project Management",
        ],
        duration: "12 months",
        certification: "Software Engineering Diploma",
      },
    },
    "Electronics and Telecommunication": {
      L3: {
        title: "Electronics Fundamentals",
        description: "Basic principles of electronics and circuits",
        modules: [
          "DC and AC Circuit Analysis",
          "Electronic Components and Measurements",
          "Basic Semiconductor Devices",
          "Introduction to Telecommunications",
        ],
        duration: "6 months",
        certification: "Electronics Technician Certificate",
      },
      L4: {
        title: "Digital Systems and Communications",
        description: "Digital electronics and communication systems",
        modules: [
          "Digital Logic Design",
          "Microcontrollers and Embedded Systems",
          "Wireless Communication Principles",
          "Network Fundamentals",
        ],
        duration: "8 months",
        certification: "Electronics Technology Certificate",
      },
      L5: {
        title: "Advanced Telecommunications",
        description:
          "Advanced concepts in telecommunications and network systems",
        modules: [
          "RF Engineering and Antenna Design",
          "Data Communications and Networking",
          "Telecommunication Systems Management",
          "Emerging Communication Technologies",
        ],
        duration: "12 months",
        certification: "Telecommunications Engineering Diploma",
      },
    },
    Accounting: {
      L3: {
        title: "Principles of Accounting",
        description: "Fundamental accounting concepts and practices",
        modules: [
          "Introduction to Financial Accounting",
          "Bookkeeping Fundamentals",
          "Basic Taxation Principles",
          "Accounting Software Applications",
        ],
        duration: "6 months",
        certification: "Accounting Assistant Certificate",
      },
      L4: {
        title: "Intermediate Accounting",
        description: "Advanced accounting techniques and applications",
        modules: [
          "Managerial Accounting",
          "Corporate Finance",
          "Auditing Principles",
          "Accounting Information Systems",
        ],
        duration: "8 months",
        certification: "Professional Accountant Certificate",
      },
      L5: {
        title: "Advanced Accounting and Financial Management",
        description: "Strategic financial management and advanced accounting",
        modules: [
          "Advanced Financial Reporting",
          "Strategic Management Accounting",
          "Tax Planning and Compliance",
          "Financial Analysis and Decision Making",
        ],
        duration: "12 months",
        certification: "Accounting Management Diploma",
      },
    },
    "Computer System Architecture": {
      L3: {
        title: "Computer Hardware Fundamentals",
        description: "Introduction to computer components and architecture",
        modules: [
          "Computer Components and Assembly",
          "Operating System Fundamentals",
          "Basic Networking Concepts",
          "Troubleshooting Techniques",
        ],
        duration: "6 months",
        certification: "Computer Technician Certificate",
      },
      L4: {
        title: "System Architecture and Design",
        description: "Design and implementation of computer systems",
        modules: [
          "Computer Organization and Architecture",
          "System Performance Analysis",
          "Storage Systems and Management",
          "Virtualization Technologies",
        ],
        duration: "8 months",
        certification: "Systems Analyst Certificate",
      },
      L5: {
        title: "Advanced Computer Architecture",
        description: "Enterprise-level system design and implementation",
        modules: [
          "Advanced Processor Architecture",
          "Distributed Systems",
          "Cloud Infrastructure Design",
          "System Security Architecture",
        ],
        duration: "12 months",
        certification: "Systems Architecture Diploma",
      },
    },
  };

  const toggleCourse = (category, level) => {
    const courseId = `${category}-${level}`;
    setExpandedCourse(expandedCourse === courseId ? null : courseId);
  };

  const filteredCourses =
    activeTab === "all" ? courses : { [activeTab]: courses[activeTab] };

  return (
    <>
      <Helmet>
        <title>Courses - GS Des Parents </title>
        <meta
          name="description"
          content="Learn about GS Des Parents's mission, vision, team, and impact. Discover how we're empowering voices and transforming communities across Rwanda through inclusive dialogue and collective action."
        />
        <meta
          name="keywords"
          content="GS Des Parents, about us, mission, vision, team, community development, Rwanda, social change"
        />
        <meta property="og:title" content="About Us - GS Des Parents" />
        <meta
          property="og:description"
          content="Empowering voices and transforming communities across Rwanda through inclusive dialogue and collective action."
        />
        <meta property="og:type" content="website" />
        <link rel="canonical" href="/about-us" />
      </Helmet>
      <PublicHeader />
      <div className="min-h- mt-16 bg-gray-50 py-8 px-4 sm:px-6 lg:px-8">
        <div className="max-w-7xl mx-auto">
          <div className="text-center">
            <h2 className="text-2xl font-extrabold text-gray-900 sm:text-5xl sm:tracking-tight lg:text-6xl">
              Technical Education Programs
            </h2>
            <p className="mt-5 max-w-xl mx-auto text-xl text-gray-500">
              Comprehensive courses designed for career advancement in technical
              fields
            </p>
          </div>

          {/* Category Filter Tabs */}
          <div className="flex flex-wrap justify-center mt-16 gap-3 mb-1">
            <button
              onClick={() => setActiveTab("all")}
              className={`px-4 py-2 rounded-full font-body font-medium transition-smooth${
                activeTab === "all"
                  ? "bg-primary text-primary-foreground"
                  : "bg-muted text-muted-foreground hover:bg-primary/10 hover:text-primary"
              }`}
            >
              All Courses
            </button>
            {Object.keys(courses).map((category) => (
              <button
                key={category}
                onClick={() => setActiveTab(category)}
                className={`px-4 py-2 rounded-full font-body font-medium transition-smooth ${
                  activeTab === category
                    ? "bg-primary text-primary-foreground"
                  : "bg-muted text-muted-foreground hover:bg-primary/10 hover:text-primary"
                }`}
              >
                {category}
              </button>
            ))}
          </div>

          {/* Courses Grid */}
          <div className="mt-12 grid gap-8 md:grid-cols-2 lg:grid-cols-3">
            {Object.entries(filteredCourses).map(([category, levels]) =>
              Object.entries(levels).map(([level, course]) => {
                const courseId = `${category}-${level}`;
                const isExpanded = expandedCourse === courseId;

                return (
                  <div
                    key={courseId}
                    className="bg-white rounded-xl shadow-md overflow-hidden transition-all duration-300 ease-in-out hover:shadow-lg"
                  >
                    <div className="p-6">
                      <div className="flex justify-between items-start">
                        <div>
                          <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-800">
                            {level}
                          </span>
                          <h3 className="mt-2 text-xl font-bold text-gray-900">
                            {course.title}
                          </h3>
                          <p className="mt-1 text-sm text-gray-500">
                            {category}
                          </p>
                        </div>
                      </div>
                      <p className="mt-4 text-gray-600">{course.description}</p>

                      <div className="mt-6 flex items-center justify-between">
                        <span className="text-sm font-medium text-gray-500">
                          {course.duration}
                        </span>
                        <button
                          onClick={() => toggleCourse(category, level)}
                          className="text-sm font-medium text-blue-600 hover:text-blue-500"
                        >
                          {isExpanded ? "Show less" : "Show details"}
                        </button>
                      </div>
                    </div>

                    {/* Expandable Details */}
                    {isExpanded && (
                      <div className="px-6 pb-6 border-t border-gray-200">
                        <div className="mt-4">
                          <h4 className="text-sm font-medium text-gray-900">
                            Course Modules
                          </h4>
                          <ul className="mt-2 space-y-1">
                            {course.modules.map((module, index) => (
                              <li
                                key={index}
                                className="text-sm text-gray-600 flex items-start"
                              >
                                <span className="text-blue-500 mr-2">•</span>
                                {module}
                              </li>
                            ))}
                          </ul>
                        </div>

                        <div className="mt-4">
                          <h4 className="text-sm font-medium text-gray-900">
                            Certification
                          </h4>
                          <p className="mt-1 text-sm text-gray-600">
                            {course.certification}
                          </p>
                        </div>

                        <div className="mt-6">
                          <button className="w-full bg-blue-600 border border-transparent rounded-md py-2 px-4 flex items-center justify-center text-sm font-medium text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500">
                            Enroll Now
                          </button>
                        </div>
                      </div>
                    )}
                  </div>
                );
              })
            )}
          </div>

          {/* Information Footer */}
          <div className="mt-16 bg-white rounded-lg shadow-md p-6">
            <h2 className="text-2xl font-bold text-gray-900">
              About Our Programs
            </h2>
            <p className="mt-4 text-gray-600">
              Our technical education programs are designed to provide hands-on,
              practical skills that are directly applicable in today's
              workforce. Each course is developed in collaboration with industry
              experts to ensure you gain the most relevant and up-to-date
              knowledge in your field.
            </p>
            <div className="mt-6 grid grid-cols-1 gap-6 sm:grid-cols-3">
              <div className="flex items-start">
                <div className="flex-shrink-0">
                  <div className="flex items-center justify-center h-10 w-10 rounded-md bg-blue-500 text-white">
                    <svg
                      className="h-6 w-6"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth="2"
                        d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253"
                      />
                    </svg>
                  </div>
                </div>
                <div className="ml-4">
                  <h3 className="text-lg font-medium text-gray-900">
                    Industry-Relevant Curriculum
                  </h3>
                  <p className="mt-2 text-gray-600">
                    Courses designed with input from industry professionals to
                    ensure you learn the most sought-after skills.
                  </p>
                </div>
              </div>

              <div className="flex items-start">
                <div className="flex-shrink-0">
                  <div className="flex items-center justify-center h-10 w-10 rounded-md bg-blue-500 text-white">
                    <svg
                      className="h-6 w-6"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth="2"
                        d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"
                      />
                    </svg>
                  </div>
                </div>
                <div className="ml-4">
                  <h3 className="text-lg font-medium text-gray-900">
                    Expert Instructors
                  </h3>
                  <p className="mt-2 text-gray-600">
                    Learn from professionals with years of experience in their
                    respective fields.
                  </p>
                </div>
              </div>

              <div className="flex items-start">
                <div className="flex-shrink-0">
                  <div className="flex items-center justify-center h-10 w-10 rounded-md bg-blue-500 text-white">
                    <svg
                      className="h-6 w-6"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth="2"
                        d="M9 12l2 2 4-4m7 2a9 9 0 11-18 0 9 9 0 0118 0z"
                      />
                    </svg>
                  </div>
                </div>
                <div className="ml-4">
                  <h3 className="text-lg font-medium text-gray-900">
                    Career Support
                  </h3>
                  <p className="mt-2 text-gray-600">
                    Get assistance with job placement and career advancement
                    after completing your program.
                  </p>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
      <Footer />
    </>
  );
};

export default CourseCatalog;
