import React, { useState, useEffect } from 'react';
import Icon from '../../../components/AppIcon';

const ImpactSection = () => {
  const [counters, setCounters] = useState({
    members: 0,
    events: 0,
    districts: 0,
    projects: 0
  });

  const finalCounts = {
    members: 500,
    events: 50,
    districts: 12,
    projects: 25
  };

  useEffect(() => {
    const duration = 2000; // 2 seconds
    const steps = 60;
    const stepDuration = duration / steps;

    const intervals = Object.keys(finalCounts)?.map(key => {
      const increment = finalCounts?.[key] / steps;
      let currentCount = 0;
      
      return setInterval(() => {
        currentCount += increment;
        if (currentCount >= finalCounts?.[key]) {
          currentCount = finalCounts?.[key];
          clearInterval(intervals?.find(interval => interval === this));
        }
        
        setCounters(prev => ({
          ...prev,
          [key]: Math.floor(currentCount)
        }));
      }, stepDuration);
    });

    return () => {
      intervals?.forEach(interval => clearInterval(interval));
    };
  }, []);

  const impactStats = [
    {
      key: 'members',
      icon: 'Users',
      label: 'Active Members',
      description: 'Community members actively participating in our initiatives'
    },
    {
      key: 'events',
      icon: 'Calendar',
      label: 'Events Hosted',
      description: 'Workshops, dialogues, and community gatherings organized'
    },
    {
      key: 'districts',
      icon: 'MapPin',
      label: 'Districts Reached',
      description: 'Geographic areas where we have active community presence'
    },
    {
      key: 'projects',
      icon: 'Briefcase',
      label: 'Projects Completed',
      description: 'Successful community development projects implemented'
    }
  ];


  return (
    <section className="py-16 lg:py-24 bg-gradient-to-br from-primary/5 to-accent/5">
      <div className="max-w-7xl mx-auto px-4 lg:px-6">
        <div className="text-center mb-16">
          <h2 className="font-heading font-bold text-3xl lg:text-4xl text-foreground mb-4">
            Our Impact
          </h2>
          <p className="font-body text-lg text-muted-foreground max-w-2xl mx-auto">
            Measuring success through the positive changes we create in our communities
          </p>
        </div>
        
        {/* Impact Statistics */}
        <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-20">
          {impactStats?.map((stat) => (
            <div
              key={stat?.key}
              className="bg-card border border-border rounded-xl p-6 text-center shadow-card hover:shadow-elevated transition-smooth hover-lift"
            >
              <div className="w-16 h-16 bg-primary/10 rounded-xl flex items-center justify-center mx-auto mb-4">
                <Icon name={stat?.icon} size={32} className="text-primary" />
              </div>
              <div className="font-heading font-bold text-3xl text-foreground mb-2">
                {counters?.[stat?.key]}+
              </div>
              <h3 className="font-body font-semibold text-foreground mb-2">
                {stat?.label}
              </h3>
              <p className="font-body text-sm text-muted-foreground leading-relaxed">
                {stat?.description}
              </p>
            </div>
          ))}
        </div>
        
      </div>
    </section>
  );
};

export default ImpactSection;