import React from 'react';

import Image from '../../../components/AppImage';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';

const EventsSection = () => {
  const upcomingEvents = [
    {
      id: 1,
      title: "Academic Year 2025/2026 Enrollment",
      description: "Join us for an open discussion on community challenges and collaborative solutions. All voices welcome.",
      image: "../../../assets/Schoolbg.jpeg",
      date: "2025-09-8",
      time: "14:00",
      location: "school background",
      category: "Forum",
      attendees: 45,
      maxAttendees: 100
    },

  ];

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    return date?.toLocaleDateString('en-GB', {
      weekday: 'long',
      day: 'numeric',
      month: 'long',
      year: 'numeric'
    });
  };

  const formatTime = (timeString) => {
    const [hours, minutes] = timeString?.split(':');
    const time = new Date();
    time?.setHours(parseInt(hours), parseInt(minutes));
    return time?.toLocaleTimeString('en-GB', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false
    });
  };

  const getAttendancePercentage = (attendees, maxAttendees) => {
    return Math.round((attendees / maxAttendees) * 100);
  };

  return (
    <section className="py-16 lg:py-24 bg-muted/30">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Section Header */}
        <div className="text-center mb-12">
          <h2 className="font-heading font-bold text-3xl lg:text-4xl text-foreground mb-4">
            Upcoming Events
          </h2>
          <p className="font-body text-lg text-muted-foreground max-w-2xl mx-auto">
            Join our community events and be part of meaningful conversations that drive positive change in Rwanda.
          </p>
        </div>

        {/* Events Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-8 mb-12">
          {upcomingEvents?.map((event) => (
            <div 
              key={event?.id}
              className="bg-card rounded-lg shadow-card hover:shadow-elevated transition-smooth overflow-hidden hover-lift"
            >
              <div className="relative overflow-hidden h-48">
                <Image
                  src={event?.image}
                  alt={event?.title}
                  className="w-full h-full object-cover"
                />
                <div className="absolute top-4 left-4">
                  <span className="bg-accent text-accent-foreground px-3 py-1 rounded-full text-sm font-medium">
                    {event?.category}
                  </span>
                </div>
                <div className="absolute top-4 right-4 bg-card/90 backdrop-blur-sm rounded-lg p-2 text-center">
                  <div className="font-heading font-bold text-lg text-primary">
                    {new Date(event.date)?.getDate()}
                  </div>
                  <div className="font-body text-xs text-muted-foreground uppercase">
                    {new Date(event.date)?.toLocaleDateString('en-GB', { month: 'short' })}
                  </div>
                </div>
              </div>

              <div className="p-6">
                <h3 className="font-heading font-semibold text-xl text-foreground mb-3">
                  {event?.title}
                </h3>

                <p className="font-body text-muted-foreground mb-4 line-clamp-2">
                  {event?.description}
                </p>

                <div className="space-y-2 mb-4">
                  <div className="flex items-center text-sm text-muted-foreground">
                    <Icon name="Calendar" size={16} className="mr-2 text-primary" />
                    <span>{formatDate(event?.date)}</span>
                  </div>
                  <div className="flex items-center text-sm text-muted-foreground">
                    <Icon name="Clock" size={16} className="mr-2 text-primary" />
                    <span>{formatTime(event?.time)}</span>
                  </div>
                  <div className="flex items-center text-sm text-muted-foreground">
                    <Icon name="MapPin" size={16} className="mr-2 text-primary" />
                    <span>{event?.location}</span>
                  </div>
                </div>

                {/* Attendance Progress */}
                <div className="mb-4">
                  <div className="flex justify-between items-center mb-2">
                    <span className="text-sm font-medium text-foreground">
                      {event?.attendees} / {event?.maxAttendees} registered
                    </span>
                    <span className="text-sm text-muted-foreground">
                      {getAttendancePercentage(event?.attendees, event?.maxAttendees)}%
                    </span>
                  </div>
                  <div className="w-full bg-muted rounded-full h-2">
                    <div 
                      className="bg-primary h-2 rounded-full transition-all duration-300"
                      style={{ width: `${getAttendancePercentage(event?.attendees, event?.maxAttendees)}%` }}
                    ></div>
                  </div>
                </div>

                <div className="flex gap-2">
                  <Button 
                    variant="default" 
                    size="sm" 
                    className="flex-1"
                    iconName="UserPlus"
                    iconPosition="left"
                    iconSize={16}
                  >
                    Register
                  </Button>
                  <Button 
                    variant="outline" 
                    size="sm"
                    iconName="Info"
                    iconSize={16}
                  >
                  </Button>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* View All Button */}
        <div className="text-center">
          <Button 
            variant="outline" 
            size="lg"
            iconName="Calendar"
            iconPosition="left"
          >
            View All Events
          </Button>
        </div>
      </div>
    </section>
  );
};

export default EventsSection;