import React, { useState } from 'react';
import Icon from '../../../components/AppIcon';
import Image from '../../../components/AppImage';
import Button from '../../../components/ui/Button';
import Input from '../../../components/ui/Input';

const PersonalDetailsTab = ({ userData, onUpdateProfile }) => {
  const [formData, setFormData] = useState({
    firstName: userData?.firstName || '',
    lastName: userData?.lastName || '',
    email: userData?.email || '',
    phone: userData?.phone || '',
    bio: userData?.bio || '',
    location: userData?.location || '',
    dateOfBirth: userData?.dateOfBirth || '',
    occupation: userData?.occupation || ''
  });

  const [profileImage, setProfileImage] = useState(userData?.avatar || '');
  const [imagePreview, setImagePreview] = useState(null);
  const [isDragOver, setIsDragOver] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [errors, setErrors] = useState({});

  const handleInputChange = (e) => {
    const { name, value } = e?.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
    
    // Clear error when user starts typing
    if (errors?.[name]) {
      setErrors(prev => ({
        ...prev,
        [name]: ''
      }));
    }
  };

  const handleImageUpload = (file) => {
    if (!file) return;

    // Validate file type
    const allowedTypes = ['image/jpeg', 'image/png', 'image/webp'];
    if (!allowedTypes?.includes(file?.type)) {
      setErrors(prev => ({
        ...prev,
        image: 'Please upload a valid image file (JPEG, PNG, or WebP)'
      }));
      return;
    }

    // Validate file size (max 5MB)
    if (file?.size > 5 * 1024 * 1024) {
      setErrors(prev => ({
        ...prev,
        image: 'Image size must be less than 5MB'
      }));
      return;
    }

    setIsUploading(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      setImagePreview(e?.target?.result);
      setProfileImage(e?.target?.result);
      setIsUploading(false);
      setErrors(prev => ({
        ...prev,
        image: ''
      }));
    };
    reader?.readAsDataURL(file);
  };

  const handleDrop = (e) => {
    e?.preventDefault();
    setIsDragOver(false);
    const file = e?.dataTransfer?.files?.[0];
    handleImageUpload(file);
  };

  const handleDragOver = (e) => {
    e?.preventDefault();
    setIsDragOver(true);
  };

  const handleDragLeave = (e) => {
    e?.preventDefault();
    setIsDragOver(false);
  };

  const validateForm = () => {
    const newErrors = {};

    if (!formData?.firstName?.trim()) {
      newErrors.firstName = 'First name is required';
    }

    if (!formData?.lastName?.trim()) {
      newErrors.lastName = 'Last name is required';
    }

    if (!formData?.email?.trim()) {
      newErrors.email = 'Email is required';
    } else if (!/\S+@\S+\.\S+/?.test(formData?.email)) {
      newErrors.email = 'Please enter a valid email address';
    }

    if (formData?.phone && !/^\+?[\d\s\-\(\)]+$/?.test(formData?.phone)) {
      newErrors.phone = 'Please enter a valid phone number';
    }

    setErrors(newErrors);
    return Object.keys(newErrors)?.length === 0;
  };

  const handleSubmit = (e) => {
    e?.preventDefault();
    
    if (!validateForm()) {
      return;
    }

    const updatedData = {
      ...formData,
      avatar: profileImage
    };

    onUpdateProfile(updatedData);
  };

  return (
    <div className="space-y-8">
      {/* Profile Picture Section */}
      <div className="bg-card border border-border rounded-lg p-6">
        <h3 className="font-heading font-semibold text-lg text-foreground mb-4">
          Profile Picture
        </h3>
        
        <div className="flex flex-col md:flex-row items-start space-y-4 md:space-y-0 md:space-x-6">
          <div className="flex-shrink-0">
            <div className="w-24 h-24 rounded-full overflow-hidden bg-muted border-2 border-border">
              <Image
                src={imagePreview || profileImage}
                alt="Profile"
                className="w-full h-full object-cover"
              />
            </div>
          </div>

          <div className="flex-1">
            <div
              className={`border-2 border-dashed rounded-lg p-6 text-center transition-colors ${
                isDragOver
                  ? 'border-primary bg-primary/5' :'border-border hover:border-primary/50'
              }`}
              onDrop={handleDrop}
              onDragOver={handleDragOver}
              onDragLeave={handleDragLeave}
            >
              {isUploading ? (
                <div className="flex items-center justify-center space-x-2">
                  <Icon name="Loader2" size={20} className="animate-spin text-primary" />
                  <span className="font-body text-sm text-muted-foreground">Uploading...</span>
                </div>
              ) : (
                <>
                  <Icon name="Upload" size={32} className="mx-auto text-muted-foreground mb-2" />
                  <p className="font-body text-sm text-foreground mb-1">
                    Drag and drop your image here, or
                  </p>
                  <label className="cursor-pointer">
                    <span className="font-body text-sm text-primary hover:text-primary/80">
                      browse files
                    </span>
                    <input
                      type="file"
                      className="hidden"
                      accept="image/jpeg,image/png,image/webp"
                      onChange={(e) => handleImageUpload(e?.target?.files?.[0])}
                    />
                  </label>
                  <p className="font-caption text-xs text-muted-foreground mt-2">
                    JPEG, PNG or WebP (max 5MB)
                  </p>
                </>
              )}
            </div>
            {errors?.image && (
              <p className="font-caption text-sm text-destructive mt-2">{errors?.image}</p>
            )}
          </div>
        </div>
      </div>
      {/* Personal Information Form */}
      <div className="bg-card border border-border rounded-lg p-6">
        <h3 className="font-heading font-semibold text-lg text-foreground mb-6">
          Personal Information
        </h3>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <Input
              label="First Name"
              type="text"
              name="firstName"
              value={formData?.firstName}
              onChange={handleInputChange}
              placeholder="Enter your first name"
              error={errors?.firstName}
              required
            />

            <Input
              label="Last Name"
              type="text"
              name="lastName"
              value={formData?.lastName}
              onChange={handleInputChange}
              placeholder="Enter your last name"
              error={errors?.lastName}
              required
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <Input
              label="Email Address"
              type="email"
              name="email"
              value={formData?.email}
              onChange={handleInputChange}
              placeholder="Enter your email"
              error={errors?.email}
              required
            />

            <Input
              label="Phone Number"
              type="tel"
              name="phone"
              value={formData?.phone}
              onChange={handleInputChange}
              placeholder="+250 xxx xxx xxx"
              error={errors?.phone}
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <Input
              label="Location"
              type="text"
              name="location"
              value={formData?.location}
              onChange={handleInputChange}
              placeholder="City, Country"
            />

            <Input
              label="Date of Birth"
              type="date"
              name="dateOfBirth"
              value={formData?.dateOfBirth}
              onChange={handleInputChange}
            />
          </div>

          <Input
            label="Occupation"
            type="text"
            name="occupation"
            value={formData?.occupation}
            onChange={handleInputChange}
            placeholder="Your profession or role"
          />

          <div>
            <label className="block font-body font-medium text-sm text-foreground mb-2">
              Bio
            </label>
            <textarea
              name="bio"
              value={formData?.bio}
              onChange={handleInputChange}
              placeholder="Tell us about yourself..."
              rows={4}
              className="w-full px-3 py-2 border border-border rounded-md bg-input text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-ring focus:border-transparent resize-none"
            />
            <p className="font-caption text-xs text-muted-foreground mt-1">
              {formData?.bio?.length}/500 characters
            </p>
          </div>

          <div className="flex justify-end space-x-4 pt-4">
            <Button
              type="button"
              variant="outline"
              onClick={() => {
                setFormData({
                  firstName: userData?.firstName || '',
                  lastName: userData?.lastName || '',
                  email: userData?.email || '',
                  phone: userData?.phone || '',
                  bio: userData?.bio || '',
                  location: userData?.location || '',
                  dateOfBirth: userData?.dateOfBirth || '',
                  occupation: userData?.occupation || ''
                });
                setImagePreview(null);
                setProfileImage(userData?.avatar || '');
                setErrors({});
              }}
            >
              Reset Changes
            </Button>
            <Button
              type="submit"
              variant="default"
              iconName="Save"
              iconPosition="left"
            >
              Save Changes
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default PersonalDetailsTab;