import React from 'react';
import Icon from '../../../components/AppIcon';

const SystemHealth = () => {
  const systemMetrics = [
    {
      id: 1,
      name: "Server Status",
      status: "healthy",
      value: "99.9%",
      description: "Uptime last 30 days",
      icon: "Server",
      color: "text-success",
      bgColor: "bg-success/10"
    },
    {
      id: 2,
      name: "Database",
      status: "healthy",
      value: "Normal",
      description: "Response time: 45ms",
      icon: "Database",
      color: "text-success",
      bgColor: "bg-success/10"
    },
    {
      id: 3,
      name: "Email Service",
      status: "warning",
      value: "0%",
      description: "Last sent: 2 min ago",
      icon: "Mail",
      color: "text-warning",
      bgColor: "bg-warning/10"
    },
    {
      id: 4,
      name: "File Storage",
      status: "warning",
      value: "78%",
      description: "Storage usage",
      icon: "HardDrive",
      color: "text-warning",
      bgColor: "bg-warning/10"
    }
  ];

  const recentBackups = [
    {
      id: 1,
      type: "Full Backup",
      timestamp: "2025-08-14 02:00:00",
      status: "completed",
      size: "2.4 GB"
    },
    {
      id: 2,
      type: "Database Backup",
      timestamp: "2025-08-14 06:00:00",
      status: "completed",
      size: "156 MB"
    },
    {
      id: 3,
      type: "Media Backup",
      timestamp: "2025-08-14 10:00:00",
      status: "in_progress",
      size: "1.8 GB"
    }
  ];

  const getStatusIcon = (status) => {
    switch (status) {
      case 'healthy':
        return { name: 'CheckCircle', color: 'text-success' };
      case 'warning':
        return { name: 'AlertTriangle', color: 'text-warning' };
      case 'error':
        return { name: 'XCircle', color: 'text-error' };
      default:
        return { name: 'Circle', color: 'text-muted-foreground' };
    }
  };

  const getBackupStatusBadge = (status) => {
    switch (status) {
      case 'completed':
        return 'bg-success/10 text-success';
      case 'in_progress':
        return 'bg-warning/10 text-warning';
      case 'failed':
        return 'bg-error/10 text-error';
      default:
        return 'bg-muted text-muted-foreground';
    }
  };

  return (
    <div className="space-y-6">
      {/* System Metrics */}
      <div className="bg-card rounded-lg border border-border p-6 shadow-card">
        <div className="flex items-center justify-between mb-6">
          <h3 className="font-heading text-lg font-semibold text-foreground">System Health</h3>
          <div className="flex items-center space-x-2">
            <Icon name="Activity" size={16} className="text-success" />
            <span className="font-body text-sm text-success">All Systems Operational</span>
          </div>
        </div>
        
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          {systemMetrics?.map((metric) => {
            const statusIcon = getStatusIcon(metric?.status);
            return (
              <div key={metric?.id} className="p-4 rounded-lg border border-border hover:border-primary/20 transition-smooth">
                <div className="flex items-center justify-between mb-3">
                  <div className={`w-10 h-10 rounded-lg ${metric?.bgColor} flex items-center justify-center`}>
                    <Icon name={metric?.icon} size={20} className={metric?.color} />
                  </div>
                  <Icon name={statusIcon?.name} size={20} className={statusIcon?.color} />
                </div>
                <h4 className="font-body font-medium text-sm text-foreground mb-1">{metric?.name}</h4>
                <p className="font-heading text-lg font-bold text-foreground mb-1">{metric?.value}</p>
                <p className="font-body text-xs text-muted-foreground">{metric?.description}</p>
              </div>
            );
          })}
        </div>
      </div>
      {/* Recent Backups */}
      <div className="bg-card rounded-lg border border-border p-6 shadow-card">
        <div className="flex items-center justify-between mb-6">
          <h3 className="font-heading text-lg font-semibold text-foreground">Recent Backups</h3>
          <button className="font-body text-sm text-primary hover:text-primary/80 transition-smooth">
            View All Backups
          </button>
        </div>
        
        <div className="space-y-3">
          {recentBackups?.map((backup) => (
            <div key={backup?.id} className="flex items-center justify-between p-4 rounded-lg bg-muted/30 hover:bg-muted/50 transition-smooth">
              <div className="flex items-center space-x-4">
                <div className="w-10 h-10 rounded-lg bg-primary/10 flex items-center justify-center">
                  <Icon name="Archive" size={20} className="text-primary" />
                </div>
                
                <div>
                  <h4 className="font-body font-medium text-sm text-foreground">{backup?.type}</h4>
                  <p className="font-body text-xs text-muted-foreground">{backup?.timestamp}</p>
                </div>
              </div>
              
              <div className="flex items-center space-x-4">
                <div className="text-right">
                  <p className="font-body text-sm text-foreground">{backup?.size}</p>
                  <span className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium ${getBackupStatusBadge(backup?.status)}`}>
                    {backup?.status === 'in_progress' ? 'In Progress' : 
                     backup?.status === 'completed' ? 'Completed' : 
                     backup?.status === 'failed' ? 'Failed' : backup?.status}
                  </span>
                </div>
                
                {backup?.status === 'in_progress' && (
                  <div className="w-6 h-6">
                    <div className="animate-spin rounded-full h-4 w-4 border-2 border-warning border-t-transparent"></div>
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
        
        <div className="mt-6 pt-4 border-t border-border">
          <div className="flex items-center justify-between text-sm">
            <span className="font-body text-muted-foreground">Next scheduled backup:</span>
            <span className="font-body font-medium text-foreground">Today at 14:00</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SystemHealth;