import React, { useState } from "react";
import { Link, useLocation } from "react-router-dom";

import Icon from "../AppIcon";
import Button from "./Button";

const PublicHeader = () => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const location = useLocation();

  const navigationItems = [
    { label: "Home", path: "/", icon: "Home" },
    { label: "About Us", path: "/about-us", icon: "Users" },
    { label: "Courses", path: "/courses", icon: "Book" },
    { label: "Contact Us", path: "/contact", icon: "Contact" },
  ];

  const moreMenuItems = [
    { name: "Administration", href: "/administration", icon: "Users" },
    { name: "Updates", href: "/events", icon: "Calendar" },
    { name: "Archive", href: "/archives", icon: "Archive" },
    { name: "Documents", href: "/documents", icon: "Files" },
    // { name: "Library", href: "/library", icon: "Library" },
  ];

  const isActivePath = (path) => location?.pathname === path;

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  return (
    <header className="fixed top-0 left-0 right-0 z-50 bg-white border-b border-gray-200 shadow-md">
      <div className="max-w-7xl mx-auto">
        <div className="flex items-center justify-between h-16 px-4 lg:px-6">
          {/* Logo */}
          <Link
            to="/"
            className="flex items-center space-x-3 hover:opacity-80 transition-opacity duration-200"
          >
            <div className="w-10 h-10 rounded-lg flex items-center justify-center">
              <img
                src="/assets/images/logo.png"
                alt="School Logo"
                className="w-8 h-8 "
              />
            </div>
            <div className="show sm:block">
              <h1 className="font-bold text-xl text-blue-800">
                GS Des Parents
              </h1>
              <p className="text-xs text-gray-600 -mt-1">
                Excellence in Education
              </p>
            </div>
          </Link>

          {/* Desktop Navigation */}
          <nav className="hidden md:flex items-center space-x-1">
            {navigationItems?.map((item) => (
              <Link
                key={item?.path}
                to={item?.path}
                className={`flex items-center space-x-2 px-3 py-2 rounded-md font-medium transition-all duration-200 ${
                  isActivePath(item?.path)
                    ? "text-blue-700 bg-blue-50"
                    : "text-gray-700 hover:text-blue-600 hover:bg-gray-100"
                }`}
              >
                <Icon name={item?.icon} size={18} />
                <span>{item?.label}</span>
              </Link>
            ))}

            {/* More Menu */}
            <div className="relative group ml-2">
              <button className="flex items-center space-x-1 px-3 py-2 rounded-md text-sm font-medium text-gray-600 hover:text-blue-600 hover:bg-gray-100 transition-all duration-200">
                <span>More</span>
                <Icon
                  name="ChevronDown"
                  size={16}
                  className="group-hover:rotate-180 transition-transform"
                />
              </button>

              <div className="absolute top-full right-0 mt-1 w-48 bg-white border border-gray-200 rounded-lg shadow-lg opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-200 z-50">
                <div className="py-2">
                  {moreMenuItems?.map((item) => (
                    <Link
                      key={item?.name}
                      to={item?.href}
                      className="flex items-center space-x-3 px-4 py-2 text-sm text-gray-700 hover:bg-blue-50 hover:text-blue-700 transition-colors duration-200"
                    >
                      <Icon name={item?.icon} size={16} />
                      <span>{item?.name}</span>
                    </Link>
                  ))}
                </div>
              </div>
            </div>
          </nav>

          {/* Desktop CTA */}
          <div className="hidden md:flex items-center space-x-3">
            {/* <Link to="/login">
              <button className="px-4 py-2 text-sm font-medium text-blue-700 hover:text-blue-800 transition-colors">
                Sign in
              </button>
            </Link> */}
            <Link to="/apply">
              <button className="px-4 py-2 bg-blue-600 text-white text-sm font-medium rounded-md hover:bg-blue-700 transition-colors shadow-sm">
                Apply Now
              </button>
            </Link>
          </div>

          {/* Mobile Menu Button */}
          <button
            onClick={toggleMobileMenu}
            className="md:hidden p-2 rounded-md text-gray-700 hover:bg-gray-100 transition-colors"
            aria-label="Toggle mobile menu"
          >
            <div className="w-5 h-5 flex flex-col justify-between">
              <span
                className={`block h-0.5 w-full bg-current transition-transform ${
                  isMobileMenuOpen ? "transform rotate-45 translate-y-2 " : ""
                }`}
              ></span>
              <span
                className={`block h-0.5 w-full bg-current opacity-100 transition-opacity ${
                  isMobileMenuOpen ? "opacity-0" : ""
                }`}
              ></span>
              <span
                className={`block h-0.5 w-full bg-current transition-transform ${
                  isMobileMenuOpen ? "transform -rotate-45 -translate-y-2" : ""
                }`}
              ></span>
            </div>
          </button>
        </div>

        {/* Mobile Menu */}
        {isMobileMenuOpen && (
          <div className="md:hidden bg-white border-t border-gray-200 animate-fade-in">
            <nav className="px-4 py-4 space-y-1">
              {navigationItems?.map((item) => (
                <Link
                  key={item?.path}
                  to={item?.path}
                  onClick={() => setIsMobileMenuOpen(false)}
                  className={`flex items-center space-x-3 px-3 py-3 rounded-md font-medium transition-colors ${
                    isActivePath(item?.path)
                      ? "text-blue-700 bg-blue-50"
                      : "text-gray-700 hover:bg-gray-100 hover:text-blue-600"
                  }`}
                >
                  <Icon name={item?.icon} size={20} />
                  <span>{item?.label}</span>
                </Link>
              ))}

              {/* More menu items in mobile */}
              <div className="pt-2 pl-3">
                <p className="text-xs font-semibold text-gray-500 uppercase tracking-wider py-2">
                  More
                </p>
                {moreMenuItems?.map((item) => (
                  <Link
                    key={item?.name}
                    to={item?.href}
                    onClick={() => setIsMobileMenuOpen(false)}
                    className="flex items-center space-x-3 px-3 py-3 rounded-md font-medium text-gray-700 hover:bg-gray-100 hover:text-blue-600 transition-colors"
                  >
                    <Icon name={item?.icon} size={20} />
                    <span>{item?.name}</span>
                  </Link>
                ))}
              </div>

              <div className="pt-4 border-t border-gray-200 space-y-3">
                <Link
                  to="/login"
                  onClick={() => setIsMobileMenuOpen(false)}
                  className="block"
                >
                  <button className="w-full text-left px-4 py-2 text-blue-700 font-medium hover:bg-blue-50 rounded-md transition-colors">
                    Sign In
                  </button>
                </Link>

                <Link
                  to="/apply"
                  onClick={() => setIsMobileMenuOpen(false)}
                  className="block"
                >
                  <button className="w-full text-left px-4 py-2 bg-blue-600 text-white font-medium rounded-md hover:bg-blue-700 transition-colors">
                    Apply Now
                  </button>
                </Link>
              </div>
            </nav>
          </div>
        )}
      </div>
    </header>
  );
};

export default PublicHeader;
