import React from 'react';
import Icon from '../../../components/AppIcon';

const MissionVisionSection = () => {
  const values = [
    {
      icon: 'Target',
      title: 'Transparency',
      description: 'We believe in open communication and accountability in all our actions and decisions.'
    },
    {
      icon: 'Users',
      title: 'Inclusivity',
      description: 'Every voice matters. We create spaces where all community members can participate and contribute.'
    },
    {
      icon: 'Lightbulb',
      title: 'Innovation',
      description: 'We embrace creative solutions and modern approaches to address community challenges.'
    },
    {
      icon: 'Heart',
      title: 'Empathy',
      description: 'We listen with compassion and work to understand diverse perspectives and experiences.'
    }
  ];

  return (
    <section className="py-16 lg:py-24 bg-background">
      <div className="max-w-7xl mx-auto px-4 lg:px-6">
        {/* Mission & Vision */}
        <div className="grid lg:grid-cols-2 gap-12 mb-20">
          {/* Mission */}
          <div className="bg-card border border-border rounded-2xl p-8 shadow-card hover:shadow-elevated transition-smooth">
            <div className="w-16 h-16 bg-primary/10 rounded-xl flex items-center justify-center mb-6">
              <Icon name="Compass" size={32} className="text-primary" />
            </div>
            <h2 className="font-heading font-bold text-2xl text-foreground mb-4">Our Mission</h2>
            <p className="font-body text-muted-foreground leading-relaxed">
             is purely to produce and send out students who are competitive on the job market.
            </p>
          </div>
          
          {/* Vision */}
          <div className="bg-card border border-border rounded-2xl p-8 shadow-card hover:shadow-elevated transition-smooth">
            <div className="w-16 h-16 bg-accent/10 rounded-xl flex items-center justify-center mb-6">
              <Icon name="Eye" size={32} className="text-accent" />
            </div>
            <h2 className="font-heading font-bold text-2xl text-foreground mb-4">Our Vision</h2>
            <p className="font-body text-muted-foreground leading-relaxed">
             To transform our school into a center of excellence for professional and technical training at a high standard in the Southern Province.
            </p>
          </div>
        </div>
        
        {/* Core Values */}
        <div className="text-center mb-12">
          <h2 className="font-heading font-bold text-3xl lg:text-4xl text-foreground mb-4">
            Our Core Values
          </h2>
          <p className="font-body text-lg text-muted-foreground max-w-2xl mx-auto">
            These principles guide everything we do and shape how we interact with our community
          </p>
        </div>
        
        <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-6">
          {values?.map((value, index) => (
            <div
              key={index}
              className="bg-card border border-border rounded-xl p-6 text-center hover:shadow-elevated transition-smooth hover-lift"
            >
              <div className="w-14 h-14 bg-primary/10 rounded-lg flex items-center justify-center mx-auto mb-4">
                <Icon name={value?.icon} size={24} className="text-primary" />
              </div>
              <h3 className="font-heading font-semibold text-lg text-foreground mb-3">
                {value?.title}
              </h3>
              <p className="font-body text-sm text-muted-foreground leading-relaxed">
                {value?.description}
              </p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default MissionVisionSection;