import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import Icon from '../AppIcon';

const AdminSidebar = ({ isCollapsed = false, onToggleCollapse }) => {
  const [expandedSections, setExpandedSections] = useState({
    content: true,
    users: false,
    settings: false,
  });
  const location = useLocation();

  const toggleSection = (section) => {
    if (isCollapsed) return;
    setExpandedSections(prev => ({
      ...prev,
      [section]: !prev?.[section]
    }));
  };

  const isActivePath = (path) => location?.pathname === path;

  const sidebarSections = [
    {
      id: 'overview',
      label: 'Overview',
      icon: 'LayoutDashboard',
      path: '/admin-panel',
      items: []
    },
    {
      id: 'content',
      label: 'Content Management',
      icon: 'FileText',
      items: [
        { label: 'Updates', path: '/admin-panel/updates', icon: 'BookOpen' },
        { label: 'Events', path: '/admin-panel/events', icon: 'Calendar' },
        { label: 'School Actions', path: '/admin-panel/events', icon: 'Action' },
        { label: 'Announcements', path: '/admin-panel/announcements', icon: 'Megaphone' },
        { label: 'Resources', path: '/admin-panel/resources', icon: 'FolderOpen' },
      ]
    },
    {
      id: 'users',
      label: 'User Management',
      icon: 'Users',
      items: [
        { label: 'Student Management', path: '/admin-panel/members', icon: 'User' },
        { label: 'Student Applying', path: '/admin-panel/students-apply', icon: 'UserPlus' },
      ]
    },
    {
      id: 'settings',
      label: 'Settings',
      icon: 'Settings',
      items: [
        { label: 'General Settings', path: '/admin-panel/settings/general', icon: 'Sliders' },
        { label: 'Email Templates', path: '/admin-panel/settings/email', icon: 'Mail' },
        { label: 'Integrations', path: '/admin-panel/settings/integrations', icon: 'Plug' },
      ]
    }
  ];

  return (
    <>
      {/* Desktop Sidebar */}
      <aside className={`fixed left-0 top-16 bottom-0 z-40 bg-card border-r border-border transition-all duration-300 ${
        isCollapsed ? 'w-16' : 'w-64'
      } hidden lg:block`}>
        <div className="flex flex-col h-full">
          {/* Collapse Toggle */}
          <div className="flex items-center justify-between p-4 border-b border-border">
            {!isCollapsed && (
              <h2 className="font-heading font-semibold text-lg text-foreground">
                Admin Panel
              </h2>
            )}
            <button
              onClick={onToggleCollapse}
              className="p-2 rounded-md hover:bg-muted transition-smooth"
              aria-label={isCollapsed ? 'Expand sidebar' : 'Collapse sidebar'}
            >
              <Icon name={isCollapsed ? 'ChevronRight' : 'ChevronLeft'} size={20} />
            </button>
          </div>

          {/* Navigation */}
          <nav className="flex-1 overflow-y-auto p-4 space-y-2">
            {sidebarSections?.map((section) => (
              <div key={section?.id}>
                {section?.path ? (
                  // Single item section
                  (<Link
                    to={section?.path}
                    className={`flex items-center space-x-3 px-3 py-2 rounded-md font-body font-medium transition-smooth hover:bg-muted ${
                      isActivePath(section?.path)
                        ? 'text-primary bg-muted' :'text-foreground hover:text-primary'
                    }`}
                    title={isCollapsed ? section?.label : ''}
                  >
                    <Icon name={section?.icon} size={20} />
                    {!isCollapsed && <span>{section?.label}</span>}
                  </Link>)
                ) : (
                  // Expandable section
                  (<>
                    <button
                      onClick={() => toggleSection(section?.id)}
                      className={`flex items-center justify-between w-full px-3 py-2 rounded-md font-body font-medium transition-smooth hover:bg-muted text-foreground hover:text-primary ${
                        isCollapsed ? 'justify-center' : ''
                      }`}
                      title={isCollapsed ? section?.label : ''}
                    >
                      <div className="flex items-center space-x-3">
                        <Icon name={section?.icon} size={20} />
                        {!isCollapsed && <span>{section?.label}</span>}
                      </div>
                      {!isCollapsed && (
                        <Icon
                          name="ChevronDown"
                          size={16}
                          className={`transition-transform ${
                            expandedSections?.[section?.id] ? 'rotate-180' : ''
                          }`}
                        />
                      )}
                    </button>
                    {/* Subsection Items */}
                    {!isCollapsed && expandedSections?.[section?.id] && (
                      <div className="ml-6 mt-2 space-y-1">
                        {section?.items?.map((item) => (
                          <Link
                            key={item?.path}
                            to={item?.path}
                            className={`flex items-center space-x-3 px-3 py-2 rounded-md font-body text-sm transition-smooth hover:bg-muted ${
                              isActivePath(item?.path)
                                ? 'text-primary bg-muted' :'text-muted-foreground hover:text-foreground'
                            }`}
                          >
                            <Icon name={item?.icon} size={16} />
                            <span>{item?.label}</span>
                          </Link>
                        ))}
                      </div>
                    )}
                  </>)
                )}
              </div>
            ))}
          </nav>

          {/* Footer */}
          {!isCollapsed && (
            <div className="p-4 border-t border-border">
              <div className="flex items-center space-x-3 px-3 py-2 bg-muted rounded-md">
                <Icon name="Shield" size={16} className="text-primary" />
                <div>
                  <p className="font-body font-medium text-xs text-foreground">GNA IntelleX</p>
                  <p className="font-caption text-xs text-muted-foreground">Security Service</p>
                </div>
              </div>
            </div>
          )}
        </div>
      </aside>
      {/* Mobile Drawer Overlay */}
      <div className={`fixed inset-0 z-50 lg:hidden ${isCollapsed ? 'hidden' : 'block'}`}>
        <div
          className="absolute inset-0 bg-black bg-opacity-50"
          onClick={onToggleCollapse}
        />
        <aside className="absolute left-0 top-0 bottom-0 w-64 bg-card border-r border-border animate-slide-in">
          <div className="flex flex-col h-full">
            {/* Header */}
            <div className="flex items-center justify-between p-4 border-b border-border">
              <h2 className="font-heading font-semibold text-lg text-foreground">
                Admin Panel
              </h2>
              <button
                onClick={onToggleCollapse}
                className="p-2 rounded-md hover:bg-muted transition-smooth"
                aria-label="Close sidebar"
              >
                <Icon name="X" size={20} />
              </button>
            </div>

            {/* Navigation */}
            <nav className="flex-1 overflow-y-auto p-4 space-y-2">
              {sidebarSections?.map((section) => (
                <div key={section?.id}>
                  {section?.path ? (
                    <Link
                      to={section?.path}
                      onClick={onToggleCollapse}
                      className={`flex items-center space-x-3 px-3 py-2 rounded-md font-body font-medium transition-smooth hover:bg-muted ${
                        isActivePath(section?.path)
                          ? 'text-primary bg-muted' :'text-foreground hover:text-primary'
                      }`}
                    >
                      <Icon name={section?.icon} size={20} />
                      <span>{section?.label}</span>
                    </Link>
                  ) : (
                    <>
                      <button
                        onClick={() => toggleSection(section?.id)}
                        className="flex items-center justify-between w-full px-3 py-2 rounded-md font-body font-medium transition-smooth hover:bg-muted text-foreground hover:text-primary"
                      >
                        <div className="flex items-center space-x-3">
                          <Icon name={section?.icon} size={20} />
                          <span>{section?.label}</span>
                        </div>
                        <Icon
                          name="ChevronDown"
                          size={16}
                          className={`transition-transform ${
                            expandedSections?.[section?.id] ? 'rotate-180' : ''
                          }`}
                        />
                      </button>

                      {expandedSections?.[section?.id] && (
                        <div className="ml-6 mt-2 space-y-1">
                          {section?.items?.map((item) => (
                            <Link
                              key={item?.path}
                              to={item?.path}
                              onClick={onToggleCollapse}
                              className={`flex items-center space-x-3 px-3 py-2 rounded-md font-body text-sm transition-smooth hover:bg-muted ${
                                isActivePath(item?.path)
                                  ? 'text-primary bg-muted' :'text-muted-foreground hover:text-foreground'
                              }`}
                            >
                              <Icon name={item?.icon} size={16} />
                              <span>{item?.label}</span>
                            </Link>
                          ))}
                        </div>
                      )}
                    </>
                  )}
                </div>
              ))}
            </nav>

            {/* Footer */}
            <div className="p-4 border-t border-border">
              <div className="flex items-center space-x-3 px-3 py-2 bg-muted rounded-md">
                <Icon name="Shield" size={16} className="text-primary" />
                <div>
                  <p className="font-body font-medium text-xs text-foreground">Admin Access</p>
                  <p className="font-caption text-xs text-muted-foreground">Full Permissions</p>
                </div>
              </div>
            </div>
          </div>
        </aside>
      </div>
    </>
  );
};

export default AdminSidebar;