import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import AuthenticatedHeader from "../../components/ui/AuthenticatedHeader";
import BreadcrumbNavigation from "../../components/ui/BreadcrumbNavigation";
import Icon from "../../components/AppIcon";
import Button from "../../components/ui/Button";
import PersonalDetailsTab from "./components/PersonalDetailsTab";
import AccountSecurityTab from "./components/AccountSecurityTab";
import PreferencesTab from "./components/PreferencesTab";
import ProfileCompletionCard from "./components/ProfileCompletionCard";
import DataExportCard from "./components/DataExportCard";

const ProfileManagement = () => {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState("personal");
  const [isLoading, setIsLoading] = useState(false);
  const [successMessage, setSuccessMessage] = useState("");
  const [errorMessage, setErrorMessage] = useState("");

  // Mock user data
  const [userData, setUserData] = useState({
    id: 1,
    firstName: "John",
    lastName: "Doe",
    email: "john.doe@example.com",
    phone: "+250 788 123 456",
    bio: `Passionate community advocate and software developer based in Kigali. \nI believe in the power of technology to drive positive social change and am excited to contribute to UNMUTE Rwanda's mission of empowering voices in our community.`,
    location: "Kigali, Rwanda",
    dateOfBirth: "1990-05-15",
    occupation: "Software Developer",
    avatar:
      "https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=400&h=400&fit=crop&crop=face",
    name: "John Doe",
    role: "member",
    joinDate: "2024-01-15",
    lastLogin: "2025-01-14 09:30:00",
  });

  const [userPreferences, setUserPreferences] = useState({
    notifications: {
      email: true,
      push: true,
      sms: false,
      eventReminders: true,
      announcements: true,
      blogUpdates: false,
      membershipUpdates: true,
    },
    privacy: {
      profileVisibility: "members",
      showEmail: false,
      showPhone: false,
      allowDirectMessages: true,
      showOnlineStatus: true,
    },
    communication: {
      language: "en",
      timezone: "Africa/Kigali",
      emailFrequency: "weekly",
      preferredContactMethod: "email",
    },
    content: {
      autoPlayVideos: false,
      showImages: true,
      compactView: false,
      darkMode: false,
    },
  });

  const tabs = [
    {
      id: "personal",
      label: "Personal Details",
      icon: "User",
      description: "Update your personal information and profile picture",
    },
    {
      id: "security",
      label: "Account Security",
      icon: "Shield",
      description: "Manage your password and active sessions",
    },
    {
      id: "preferences",
      label: "Preferences",
      icon: "Settings",
      description: "Customize your notifications and privacy settings",
    },
    {
      id: "data",
      label: "Data & Privacy",
      icon: "Download",
      description: "Export your data or deactivate your account",
    },
  ];

  // Calculate profile completion
  const calculateProfileCompletion = () => {
    const requiredFields = [
      { field: "firstName", section: "Personal Details" },
      { field: "lastName", section: "Personal Details" },
      { field: "email", section: "Personal Details" },
      { field: "phone", section: "Contact Information" },
      { field: "bio", section: "Bio" },
      { field: "avatar", section: "Profile Picture" },
    ];

    const completedFields = requiredFields?.filter(({ field }) => {
      const value = userData?.[field];
      return value && value?.toString()?.trim() !== "";
    });

    const percentage = Math.round(
      (completedFields?.length / requiredFields?.length) * 100
    );

    const completedSections = [
      ...new Set(completedFields.map(({ section }) => section)),
    ];
    const allSections = [
      ...new Set(requiredFields.map(({ section }) => section)),
    ];
    const missingSections = allSections
      ?.filter((section) => !completedSections?.includes(section))
      ?.map((section) => ({
        name: section,
        description: getDescriptionForSection(section),
        action: section?.toLowerCase()?.replace(" ", "-"),
      }));

    return {
      percentage,
      completedSections,
      missingSections,
    };
  };

  const getDescriptionForSection = (section) => {
    const descriptions = {
      "Personal Details": "Add your first and last name",
      "Contact Information": "Add your phone number",
      Bio: "Write a brief description about yourself",
      "Profile Picture": "Upload a profile photo",
      Preferences: "Set your notification preferences",
      Security: "Update your password and security settings",
    };
    return descriptions?.[section] || "Complete this section";
  };

  const showMessage = (message, type = "success") => {
    if (type === "success") {
      setSuccessMessage(message);
      setErrorMessage("");
    } else {
      setErrorMessage(message);
      setSuccessMessage("");
    }

    setTimeout(() => {
      setSuccessMessage("");
      setErrorMessage("");
    }, 5000);
  };

  const handleUpdateProfile = async (updatedData) => {
    setIsLoading(true);

    try {
      // Simulate API call
      await new Promise((resolve) => setTimeout(resolve, 1000));

      setUserData((prev) => ({
        ...prev,
        ...updatedData,
      }));

      showMessage("Profile updated successfully!");
    } catch (error) {
      showMessage("Failed to update profile. Please try again.", "error");
    } finally {
      setIsLoading(false);
    }
  };

  const handlePasswordChange = async (passwordData) => {
    // Simulate API call
    await new Promise((resolve) => setTimeout(resolve, 1500));

    // Mock validation
    if (passwordData?.currentPassword !== "currentpass123") {
      throw new Error("Current password is incorrect");
    }

    showMessage("Password changed successfully!");
  };

  const handleSessionManagement = (action, sessionId = null) => {
    if (action === "terminate") {
      showMessage(`Session terminated successfully.`);
    } else if (action === "terminateAll") {
      showMessage("All other sessions have been terminated.");
    }
  };

  const handleUpdatePreferences = (newPreferences) => {
    setUserPreferences(newPreferences);
    showMessage("Preferences updated successfully!");
  };

  const handleExportData = async (selectedData) => {
    // Simulate export process
    await new Promise((resolve) => setTimeout(resolve, 2000));

    // Create mock download
    const exportData = {
      exportDate: new Date()?.toISOString(),
      userData: selectedData?.includes("personalInfo") ? userData : null,
      preferences: selectedData?.includes("preferences")
        ? userPreferences
        : null,
      // Add other data types as needed
    };

    const blob = new Blob([JSON.stringify(exportData, null, 2)], {
      type: "application/json",
    });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `GS Des Parents-data-export-${
      new Date()?.toISOString()?.split("T")?.[0]
    }.json`;
    document.body?.appendChild(a);
    a?.click();
    document.body?.removeChild(a);
    URL.revokeObjectURL(url);

    showMessage("Data export completed successfully!");
  };

  const handleDeactivateAccount = (reason) => {
    // In a real app, this would call an API
    console.log("Account deactivation requested:", reason);
    showMessage(
      "Account deactivation request submitted. You will receive a confirmation email shortly."
    );
  };

  const handleCompleteSection = (action) => {
    // Navigate to appropriate tab based on action
    const tabMapping = {
      "personal-details": "personal",
      "contact-information": "personal",
      bio: "personal",
      "profile-picture": "personal",
      preferences: "preferences",
      security: "security",
    };

    const targetTab = tabMapping?.[action] || "personal";
    setActiveTab(targetTab);
  };

  const completionData = calculateProfileCompletion();

  useEffect(() => {
    // Scroll to top when component mounts
    window.scrollTo(0, 0);
  }, []);

  return (
    <div className="min-h-screen bg-background">
      <AuthenticatedHeader user={userData} />
      <main className="pt-16">
        <div className="max-w-6xl mx-auto px-4 lg:px-6 py-8">
          <BreadcrumbNavigation />

          {/* Page Header */}
          <div className="mb-8">
            <div className="flex items-center justify-between">
              <div>
                <h1 className="font-heading font-bold text-3xl text-foreground mb-2">
                  Profile Management
                </h1>
                <p className="font-body text-muted-foreground">
                  Manage your personal information, security settings, and
                  preferences
                </p>
              </div>
              <Button
                variant="outline"
                iconName="ArrowLeft"
                iconPosition="left"
                onClick={() => navigate("/member-dashboard")}
              >
                Back to Dashboard
              </Button>
            </div>
          </div>

          {/* Success/Error Messages */}
          {successMessage && (
            <div className="mb-6 bg-success/10 border border-success/20 rounded-lg p-4">
              <div className="flex items-center space-x-3">
                <Icon name="CheckCircle" size={20} className="text-success" />
                <p className="font-body text-sm text-success">
                  {successMessage}
                </p>
              </div>
            </div>
          )}

          {errorMessage && (
            <div className="mb-6 bg-destructive/10 border border-destructive/20 rounded-lg p-4">
              <div className="flex items-center space-x-3">
                <Icon
                  name="AlertCircle"
                  size={20}
                  className="text-destructive"
                />
                <p className="font-body text-sm text-destructive">
                  {errorMessage}
                </p>
              </div>
            </div>
          )}

          {/* Profile Completion Card */}
          <ProfileCompletionCard
            completionData={completionData}
            onCompleteSection={handleCompleteSection}
          />

          {/* Tab Navigation */}
          <div className="bg-card border border-border rounded-lg mb-8">
            <div className="border-b border-border">
              <nav className="flex space-x-8 px-6" aria-label="Profile tabs">
                {tabs?.map((tab) => (
                  <button
                    key={tab?.id}
                    onClick={() => setActiveTab(tab?.id)}
                    className={`flex items-center space-x-2 py-4 px-2 border-b-2 font-body font-medium text-sm transition-colors ${
                      activeTab === tab?.id
                        ? "border-primary text-primary"
                        : "border-transparent text-muted-foreground hover:text-foreground hover:border-muted-foreground"
                    }`}
                  >
                    <Icon name={tab?.icon} size={18} />
                    <span className="hidden sm:inline">{tab?.label}</span>
                  </button>
                ))}
              </nav>
            </div>

            {/* Tab Description */}
            <div className="px-6 py-4 bg-muted/30">
              <p className="font-caption text-sm text-muted-foreground">
                {tabs?.find((tab) => tab?.id === activeTab)?.description}
              </p>
            </div>
          </div>

          {/* Tab Content */}
          <div
            className={`transition-opacity duration-200 ${
              isLoading ? "opacity-50" : "opacity-100"
            }`}
          >
            {activeTab === "personal" && (
              <PersonalDetailsTab
                userData={userData}
                onUpdateProfile={handleUpdateProfile}
              />
            )}

            {activeTab === "security" && (
              <AccountSecurityTab
                onPasswordChange={handlePasswordChange}
                onSessionManagement={handleSessionManagement}
              />
            )}

            {activeTab === "preferences" && (
              <PreferencesTab
                userPreferences={userPreferences}
                onUpdatePreferences={handleUpdatePreferences}
              />
            )}

            {activeTab === "data" && (
              <DataExportCard
                onExportData={handleExportData}
                onDeactivateAccount={handleDeactivateAccount}
              />
            )}
          </div>

          {/* Loading Overlay */}
          {isLoading && (
            <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
              <div className="bg-card rounded-lg p-6 flex items-center space-x-3">
                <Icon
                  name="Loader2"
                  size={24}
                  className="animate-spin text-primary"
                />
                <p className="font-body text-foreground">Updating profile...</p>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default ProfileManagement;
