import React, { useState } from 'react';
import AuthenticatedHeader from '../../components/ui/AuthenticatedHeader';
import AdminSidebar from '../../components/ui/AdminSidebar';
import BreadcrumbNavigation from '../../components/ui/BreadcrumbNavigation';
import DashboardStats from './components/DashboardStats';
import RecentActivity from './components/RecentActivity';
import QuickActions from './components/QuickActions';
import ContentOverview from './components/ContentOverview';
import MemberInsights from './components/MemberInsights';
import SystemHealth from './components/SystemHealth';
import Icon from '../../components/AppIcon';

const AdminPanel = () => {
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [activeTab, setActiveTab] = useState('overview');

  const adminUser = {
    name: "Admin User",
    avatar: "https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150&h=150&fit=crop&crop=face",
    role: "admin"
  };

  const tabs = [
    { id: 'overview', label: 'Overview', icon: 'LayoutDashboard' },
    { id: 'content', label: 'Content', icon: 'FileText' },
    { id: 'members', label: 'Members', icon: 'Users' },
    { id: 'system', label: 'System', icon: 'Settings' }
  ];

  const handleToggleSidebar = () => {
    setSidebarCollapsed(!sidebarCollapsed);
  };

  const renderTabContent = () => {
    switch (activeTab) {
      case 'overview':
        return (
          <div className="space-y-8">
            <DashboardStats />
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <RecentActivity />
              <QuickActions />
            </div>
          </div>
        );
      case 'content':
        return <ContentOverview />;
      case 'members':
        return <MemberInsights />;
      case 'system':
        return <SystemHealth />;
      default:
        return (
          <div className="space-y-8">
            <DashboardStats />
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <RecentActivity />
              <QuickActions />
            </div>
          </div>
        );
    }
  };

  return (
    <div className="min-h-screen bg-background">
      <AuthenticatedHeader user={adminUser} />
      <AdminSidebar 
        isCollapsed={sidebarCollapsed} 
        onToggleCollapse={handleToggleSidebar} 
      />
      <main className={`transition-all duration-300 ${
        sidebarCollapsed ? 'lg:ml-16' : 'lg:ml-64'
      } pt-16`}>
        <div className="p-6 lg:p-8">
          {/* Page Header */}
          <div className="mb-8">
            <BreadcrumbNavigation />
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between">
              <div>
                <h1 className="font-heading text-3xl font-bold text-foreground mb-2">
                  Admin Panel
                </h1>
                <p className="font-body text-muted-foreground">
                  Manage your school system and monitor system performance
                </p>
              </div>
              
              <div className="flex items-center space-x-4 mt-4 sm:mt-0">
                <div className="flex items-center space-x-2 px-3 py-2 bg-success/10 rounded-lg">
                  <Icon name="Shield" size={16} className="text-success" />
                  <span className="font-body text-sm text-success font-medium">Admin Access</span>
                </div>
                
                <button 
                  onClick={handleToggleSidebar}
                  className="lg:hidden p-2 rounded-md border border-border hover:bg-muted transition-smooth"
                  aria-label="Toggle sidebar"
                >
                  <Icon name="Menu" size={20} />
                </button>
              </div>
            </div>
          </div>

          {/* Tab Navigation */}
          <div className="mb-8">
            <div className="border-b border-border">
              <nav className="flex space-x-8 overflow-x-auto">
                {tabs?.map((tab) => (
                  <button
                    key={tab?.id}
                    onClick={() => setActiveTab(tab?.id)}
                    className={`flex items-center space-x-2 py-4 px-1 border-b-2 font-body font-medium text-sm whitespace-nowrap transition-smooth ${
                      activeTab === tab?.id
                        ? 'border-primary text-primary' :'border-transparent text-muted-foreground hover:text-foreground hover:border-muted-foreground'
                    }`}
                  >
                    <Icon name={tab?.icon} size={18} />
                    <span>{tab?.label}</span>
                  </button>
                ))}
              </nav>
            </div>
          </div>

          {/* Tab Content */}
          <div className="animate-fade-in">
            {renderTabContent()}
          </div>
        </div>
      </main>
    </div>
  );
};

export default AdminPanel;