import React, { useState } from 'react';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import { Checkbox } from '../../../components/ui/Checkbox';

const DataExportCard = ({ onExportData, onDeactivateAccount }) => {
  const [exportOptions, setExportOptions] = useState({
    personalInfo: true,
    activityHistory: false,
    preferences: true,
    communications: false,
    eventHistory: true
  });
  const [isExporting, setIsExporting] = useState(false);
  const [showDeactivateConfirm, setShowDeactivateConfirm] = useState(false);
  const [deactivateReason, setDeactivateReason] = useState('');

  const exportDataTypes = [
    {
      key: 'personalInfo',
      label: 'Personal Information',
      description: 'Name, email, phone, bio, and profile details',
      icon: 'User'
    },
    {
      key: 'activityHistory',
      label: 'Activity History',
      description: 'Login history, page visits, and interactions',
      icon: 'Activity'
    },
    {
      key: 'preferences',
      label: 'Preferences & Settings',
      description: 'Notification settings, privacy preferences',
      icon: 'Settings'
    },
    {
      key: 'communications',
      label: 'Communications',
      description: 'Messages, comments, and forum posts',
      icon: 'MessageSquare'
    },
    {
      key: 'eventHistory',
      label: 'Event History',
      description: 'Events attended, RSVPs, and participation',
      icon: 'Calendar'
    }
  ];

  const deactivateReasons = [
    'Taking a break from social platforms',
    'Privacy concerns',
    'Too many notifications',
    'Not finding value in the community',
    'Technical issues',
    'Other (please specify)'
  ];

  const handleExportOptionChange = (key, checked) => {
    setExportOptions(prev => ({
      ...prev,
      [key]: checked
    }));
  };

  const handleExportData = async () => {
    setIsExporting(true);
    
    try {
      const selectedData = Object.keys(exportOptions)?.filter(key => exportOptions?.[key]);
      await onExportData(selectedData);
    } catch (error) {
      console.error('Export failed:', error);
    } finally {
      setIsExporting(false);
    }
  };

  const handleDeactivateAccount = () => {
    if (!deactivateReason?.trim()) {
      return;
    }
    
    onDeactivateAccount(deactivateReason);
    setShowDeactivateConfirm(false);
  };

  const hasSelectedExportOptions = Object.values(exportOptions)?.some(option => option);

  return (
    <div className="space-y-6">
      {/* Data Export Section */}
      <div className="bg-card border border-border rounded-lg p-6">
        <div className="flex items-center space-x-3 mb-6">
          <Icon name="Download" size={24} className="text-primary" />
          <div>
            <h3 className="font-heading font-semibold text-lg text-foreground">
              Export Your Data
            </h3>
            <p className="font-caption text-sm text-muted-foreground">
              Download a copy of your personal data and activity
            </p>
          </div>
        </div>

        <div className="space-y-4 mb-6">
          {exportDataTypes?.map((dataType) => (
            <div
              key={dataType?.key}
              className="flex items-start space-x-3 p-3 border border-border rounded-lg hover:bg-muted/50 transition-colors"
            >
              <Checkbox
                checked={exportOptions?.[dataType?.key]}
                onChange={(e) => handleExportOptionChange(dataType?.key, e?.target?.checked)}
                className="mt-1"
              />
              <div className="flex items-start space-x-3 flex-1">
                <div className="w-8 h-8 bg-primary/10 rounded-lg flex items-center justify-center flex-shrink-0">
                  <Icon name={dataType?.icon} size={16} className="text-primary" />
                </div>
                <div>
                  <h4 className="font-body font-medium text-sm text-foreground">
                    {dataType?.label}
                  </h4>
                  <p className="font-caption text-xs text-muted-foreground">
                    {dataType?.description}
                  </p>
                </div>
              </div>
            </div>
          ))}
        </div>

        <div className="flex items-center justify-between p-4 bg-muted/50 rounded-lg">
          <div className="flex items-center space-x-3">
            <Icon name="Info" size={20} className="text-primary" />
            <div>
              <p className="font-body font-medium text-sm text-foreground">
                Export Format
              </p>
              <p className="font-caption text-xs text-muted-foreground">
                Data will be exported as a ZIP file containing JSON and CSV files
              </p>
            </div>
          </div>
          <Button
            variant="default"
            iconName="Download"
            iconPosition="left"
            loading={isExporting}
            disabled={!hasSelectedExportOptions}
            onClick={handleExportData}
          >
            {isExporting ? 'Preparing Export...' : 'Export Data'}
          </Button>
        </div>
      </div>
      {/* Account Deactivation Section */}
      <div className="bg-card border border-destructive/20 rounded-lg p-6">
        <div className="flex items-center space-x-3 mb-6">
          <Icon name="AlertTriangle" size={24} className="text-destructive" />
          <div>
            <h3 className="font-heading font-semibold text-lg text-foreground">
              Account Deactivation
            </h3>
            <p className="font-caption text-sm text-muted-foreground">
              Temporarily deactivate your account and data
            </p>
          </div>
        </div>

        {!showDeactivateConfirm ? (
          <div className="space-y-4">
            <div className="bg-destructive/5 border border-destructive/20 rounded-lg p-4">
              <h4 className="font-body font-medium text-sm text-foreground mb-2">
                What happens when you deactivate:
              </h4>
              <ul className="space-y-1">
                <li className="flex items-center space-x-2 font-caption text-xs text-muted-foreground">
                  <Icon name="Minus" size={12} className="text-destructive" />
                  <span>Your profile will be hidden from other members</span>
                </li>
                <li className="flex items-center space-x-2 font-caption text-xs text-muted-foreground">
                  <Icon name="Minus" size={12} className="text-destructive" />
                  <span>You won't receive notifications or emails</span>
                </li>
                <li className="flex items-center space-x-2 font-caption text-xs text-muted-foreground">
                  <Icon name="Minus" size={12} className="text-destructive" />
                  <span>Your data will be preserved for reactivation</span>
                </li>
                <li className="flex items-center space-x-2 font-caption text-xs text-muted-foreground">
                  <Icon name="Plus" size={12} className="text-success" />
                  <span>You can reactivate anytime by logging in</span>
                </li>
              </ul>
            </div>

            <div className="flex justify-end">
              <Button
                variant="destructive"
                iconName="UserX"
                iconPosition="left"
                onClick={() => setShowDeactivateConfirm(true)}
              >
                Deactivate Account
              </Button>
            </div>
          </div>
        ) : (
          <div className="space-y-6">
            <div>
              <label className="block font-body font-medium text-sm text-foreground mb-3">
                Please tell us why you're deactivating your account:
              </label>
              <div className="space-y-2">
                {deactivateReasons?.map((reason, index) => (
                  <label
                    key={index}
                    className="flex items-center space-x-3 p-3 border border-border rounded-lg hover:bg-muted/50 cursor-pointer transition-colors"
                  >
                    <input
                      type="radio"
                      name="deactivateReason"
                      value={reason}
                      checked={deactivateReason === reason}
                      onChange={(e) => setDeactivateReason(e?.target?.value)}
                      className="w-4 h-4 text-primary border-border focus:ring-primary"
                    />
                    <span className="font-body text-sm text-foreground">{reason}</span>
                  </label>
                ))}
              </div>
            </div>

            {deactivateReason === 'Other (please specify)' && (
              <div>
                <label className="block font-body font-medium text-sm text-foreground mb-2">
                  Please specify:
                </label>
                <textarea
                  value={deactivateReason}
                  onChange={(e) => setDeactivateReason(e?.target?.value)}
                  placeholder="Tell us more about your reason..."
                  rows={3}
                  className="w-full px-3 py-2 border border-border rounded-md bg-input text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-ring focus:border-transparent resize-none"
                />
              </div>
            )}

            <div className="flex justify-between space-x-4">
              <Button
                variant="outline"
                onClick={() => {
                  setShowDeactivateConfirm(false);
                  setDeactivateReason('');
                }}
              >
                Cancel
              </Button>
              <Button
                variant="destructive"
                iconName="UserX"
                iconPosition="left"
                disabled={!deactivateReason?.trim()}
                onClick={handleDeactivateAccount}
              >
                Confirm Deactivation
              </Button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DataExportCard;