import React, { useState } from 'react';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import Input from '../../../components/ui/Input';

const AccountSecurityTab = ({ onPasswordChange, onSessionManagement }) => {
  const [passwordData, setPasswordData] = useState({
    currentPassword: '',
    newPassword: '',
    confirmPassword: ''
  });
  const [passwordStrength, setPasswordStrength] = useState(0);
  const [showPasswords, setShowPasswords] = useState({
    current: false,
    new: false,
    confirm: false
  });
  const [errors, setErrors] = useState({});
  const [isChangingPassword, setIsChangingPassword] = useState(false);

  // Mock active sessions data
  const activeSessions = [
    {
      id: 1,
      device: "Chrome on Windows",
      location: "Kigali, Rwanda",
      ipAddress: "192.168.1.100",
      lastActive: "2025-01-14 10:15:00",
      isCurrent: true
    },
    {
      id: 2,
      device: "Safari on iPhone",
      location: "Kigali, Rwanda",
      ipAddress: "192.168.1.101",
      lastActive: "2025-01-13 18:30:00",
      isCurrent: false
    },
    {
      id: 3,
      device: "Firefox on Ubuntu",
      location: "Butare, Rwanda",
      ipAddress: "192.168.2.50",
      lastActive: "2025-01-12 14:45:00",
      isCurrent: false
    }
  ];

  const calculatePasswordStrength = (password) => {
    let strength = 0;
    if (password?.length >= 8) strength += 25;
    if (/[a-z]/?.test(password)) strength += 25;
    if (/[A-Z]/?.test(password)) strength += 25;
    if (/[0-9]/?.test(password)) strength += 15;
    if (/[^A-Za-z0-9]/?.test(password)) strength += 10;
    return Math.min(strength, 100);
  };

  const getPasswordStrengthColor = (strength) => {
    if (strength < 30) return 'bg-destructive';
    if (strength < 60) return 'bg-warning';
    if (strength < 80) return 'bg-accent';
    return 'bg-success';
  };

  const getPasswordStrengthText = (strength) => {
    if (strength < 30) return 'Weak';
    if (strength < 60) return 'Fair';
    if (strength < 80) return 'Good';
    return 'Strong';
  };

  const handlePasswordChange = (e) => {
    const { name, value } = e?.target;
    setPasswordData(prev => ({
      ...prev,
      [name]: value
    }));

    if (name === 'newPassword') {
      setPasswordStrength(calculatePasswordStrength(value));
    }

    // Clear errors when user starts typing
    if (errors?.[name]) {
      setErrors(prev => ({
        ...prev,
        [name]: ''
      }));
    }
  };

  const togglePasswordVisibility = (field) => {
    setShowPasswords(prev => ({
      ...prev,
      [field]: !prev?.[field]
    }));
  };

  const validatePasswordForm = () => {
    const newErrors = {};

    if (!passwordData?.currentPassword) {
      newErrors.currentPassword = 'Current password is required';
    }

    if (!passwordData?.newPassword) {
      newErrors.newPassword = 'New password is required';
    } else if (passwordData?.newPassword?.length < 8) {
      newErrors.newPassword = 'Password must be at least 8 characters long';
    }

    if (!passwordData?.confirmPassword) {
      newErrors.confirmPassword = 'Please confirm your new password';
    } else if (passwordData?.newPassword !== passwordData?.confirmPassword) {
      newErrors.confirmPassword = 'Passwords do not match';
    }

    if (passwordData?.currentPassword === passwordData?.newPassword) {
      newErrors.newPassword = 'New password must be different from current password';
    }

    setErrors(newErrors);
    return Object.keys(newErrors)?.length === 0;
  };

  const handlePasswordSubmit = async (e) => {
    e?.preventDefault();
    
    if (!validatePasswordForm()) {
      return;
    }

    setIsChangingPassword(true);
    
    try {
      await onPasswordChange(passwordData);
      setPasswordData({
        currentPassword: '',
        newPassword: '',
        confirmPassword: ''
      });
      setPasswordStrength(0);
    } catch (error) {
      setErrors({ submit: 'Failed to change password. Please try again.' });
    } finally {
      setIsChangingPassword(false);
    }
  };

  const handleTerminateSession = (sessionId) => {
    onSessionManagement('terminate', sessionId);
  };

  const handleTerminateAllSessions = () => {
    onSessionManagement('terminateAll');
  };

  const formatLastActive = (timestamp) => {
    const date = new Date(timestamp);
    const now = new Date();
    const diffInHours = Math.floor((now - date) / (1000 * 60 * 60));
    
    if (diffInHours < 1) return 'Active now';
    if (diffInHours < 24) return `${diffInHours} hours ago`;
    return date?.toLocaleDateString('en-GB');
  };

  return (
    <div className="space-y-8">
      {/* Change Password Section */}
      <div className="bg-card border border-border rounded-lg p-6">
        <div className="flex items-center space-x-3 mb-6">
          <Icon name="Lock" size={24} className="text-primary" />
          <h3 className="font-heading font-semibold text-lg text-foreground">
            Change Password
          </h3>
        </div>

        <form onSubmit={handlePasswordSubmit} className="space-y-6">
          <div className="relative">
            <Input
              label="Current Password"
              type={showPasswords?.current ? "text" : "password"}
              name="currentPassword"
              value={passwordData?.currentPassword}
              onChange={handlePasswordChange}
              placeholder="Enter your current password"
              error={errors?.currentPassword}
              required
            />
            <button
              type="button"
              onClick={() => togglePasswordVisibility('current')}
              className="absolute right-3 top-9 text-muted-foreground hover:text-foreground"
            >
              <Icon name={showPasswords?.current ? "EyeOff" : "Eye"} size={20} />
            </button>
          </div>

          <div className="relative">
            <Input
              label="New Password"
              type={showPasswords?.new ? "text" : "password"}
              name="newPassword"
              value={passwordData?.newPassword}
              onChange={handlePasswordChange}
              placeholder="Enter your new password"
              error={errors?.newPassword}
              required
            />
            <button
              type="button"
              onClick={() => togglePasswordVisibility('new')}
              className="absolute right-3 top-9 text-muted-foreground hover:text-foreground"
            >
              <Icon name={showPasswords?.new ? "EyeOff" : "Eye"} size={20} />
            </button>
            
            {passwordData?.newPassword && (
              <div className="mt-3">
                <div className="flex items-center justify-between mb-2">
                  <span className="font-caption text-sm text-muted-foreground">
                    Password Strength
                  </span>
                  <span className={`font-caption text-sm font-medium ${
                    passwordStrength < 30 ? 'text-destructive' :
                    passwordStrength < 60 ? 'text-warning' :
                    passwordStrength < 80 ? 'text-accent' : 'text-success'
                  }`}>
                    {getPasswordStrengthText(passwordStrength)}
                  </span>
                </div>
                <div className="w-full bg-muted rounded-full h-2">
                  <div
                    className={`h-2 rounded-full transition-all duration-300 ${getPasswordStrengthColor(passwordStrength)}`}
                    style={{ width: `${passwordStrength}%` }}
                  />
                </div>
              </div>
            )}
          </div>

          <div className="relative">
            <Input
              label="Confirm New Password"
              type={showPasswords?.confirm ? "text" : "password"}
              name="confirmPassword"
              value={passwordData?.confirmPassword}
              onChange={handlePasswordChange}
              placeholder="Confirm your new password"
              error={errors?.confirmPassword}
              required
            />
            <button
              type="button"
              onClick={() => togglePasswordVisibility('confirm')}
              className="absolute right-3 top-9 text-muted-foreground hover:text-foreground"
            >
              <Icon name={showPasswords?.confirm ? "EyeOff" : "Eye"} size={20} />
            </button>
          </div>

          {errors?.submit && (
            <div className="bg-destructive/10 border border-destructive/20 rounded-md p-3">
              <p className="font-body text-sm text-destructive">{errors?.submit}</p>
            </div>
          )}

          <div className="flex justify-end">
            <Button
              type="submit"
              variant="default"
              loading={isChangingPassword}
              iconName="Save"
              iconPosition="left"
            >
              Update Password
            </Button>
          </div>
        </form>
      </div>
      {/* Active Sessions Section */}
      <div className="bg-card border border-border rounded-lg p-6">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center space-x-3">
            <Icon name="Monitor" size={24} className="text-primary" />
            <h3 className="font-heading font-semibold text-lg text-foreground">
              Active Sessions
            </h3>
          </div>
          <Button
            variant="outline"
            size="sm"
            iconName="LogOut"
            iconPosition="left"
            onClick={handleTerminateAllSessions}
          >
            End All Sessions
          </Button>
        </div>

        <div className="space-y-4">
          {activeSessions?.map((session) => (
            <div
              key={session?.id}
              className="flex items-center justify-between p-4 border border-border rounded-lg hover:bg-muted/50 transition-colors"
            >
              <div className="flex items-center space-x-4">
                <div className="w-10 h-10 bg-primary/10 rounded-lg flex items-center justify-center">
                  <Icon 
                    name={session?.device?.includes('iPhone') ? 'Smartphone' : 'Monitor'} 
                    size={20} 
                    className="text-primary" 
                  />
                </div>
                <div>
                  <div className="flex items-center space-x-2">
                    <h4 className="font-body font-medium text-foreground">
                      {session?.device}
                    </h4>
                    {session?.isCurrent && (
                      <span className="px-2 py-1 bg-success/10 text-success text-xs font-medium rounded-full">
                        Current
                      </span>
                    )}
                  </div>
                  <p className="font-caption text-sm text-muted-foreground">
                    {session?.location} • {session?.ipAddress}
                  </p>
                  <p className="font-caption text-xs text-muted-foreground">
                    {formatLastActive(session?.lastActive)}
                  </p>
                </div>
              </div>

              {!session?.isCurrent && (
                <Button
                  variant="ghost"
                  size="sm"
                  iconName="X"
                  onClick={() => handleTerminateSession(session?.id)}
                  className="text-destructive hover:text-destructive"
                >
                  End Session
                </Button>
              )}
            </div>
          ))}
        </div>

        <div className="mt-6 p-4 bg-muted/50 rounded-lg">
          <div className="flex items-start space-x-3">
            <Icon name="Shield" size={20} className="text-primary mt-0.5" />
            <div>
              <h4 className="font-body font-medium text-foreground mb-1">
                Security Tip
              </h4>
              <p className="font-caption text-sm text-muted-foreground">
                If you notice any suspicious activity or unrecognized devices, 
                change your password immediately and end all sessions.
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AccountSecurityTab;