import React, { useState } from 'react';
import Icon from '../../../components/AppIcon';
import Image from '../../../components/AppImage';

const PhotoGallery = () => {
  const [selectedImage, setSelectedImage] = useState(null);

  const galleryImages = [
    {
      id: 1,
      src: '../../../assets/images/events/workshop.jpeg',
      alt: 'Workshop Session',
      category: 'Training',
      title: 'School Workshop',
      description: 'Engaging students in interactive learning activities'
    },
    {
      id: 2,
      src: '../../../assets/images/events/workshop2.jpeg',
      alt: 'Youth leadership workshop',
      category: 'Training',
      title: 'Youth Leadership Workshop',
      description: 'Engaging students in interactive learning activities'
    },
    {
      id: 3,
      src: 'https://images.unsplash.com/photo-1517486808906-6ca8b3f04846?w=600&h=400&fit=crop',
      alt: 'Community project launch',
      category: 'Projects',
      title: 'Community Project Launch',
      description: 'Launching a new initiative to support local entrepreneurs'
    },
    {
      id: 4,
      src: '../../../assets/images/events/volleyball2025.jpeg',
      alt: 'sports Year',
      category: 'Sports',
      title: 'Volleyball Tournament 2025',
      description: 'Our yearly gathering bringing together all community members'
    },
    {
      id: 5,
      src: '../../../assets/images/events/football2025.jpeg',
      alt: 'sports Year',
      category: 'Sports',
      title: 'Football Tournament 2025',
      description: 'Our yearly gathering bringing together all community members'
    },,
    {
      id: 6,
      src: '../../../assets/images/events/Student.jpg',
      alt: 'sports Year',
      category: 'Projects',
      title: 'Open Day 2023-2024',
      description: 'Our student presenting their projects called JobBox'
    },
  ];

  const categories = ['All', ...new Set(galleryImages.map(img => img.category))];
  const [activeCategory, setActiveCategory] = useState('All');

  const filteredImages = activeCategory === 'All' 
    ? galleryImages 
    : galleryImages?.filter(img => img?.category === activeCategory);

  const openModal = (image) => {
    setSelectedImage(image);
  };

  const closeModal = () => {
    setSelectedImage(null);
  };

  const nextImage = () => {
    const currentIndex = filteredImages?.findIndex(img => img?.id === selectedImage?.id);
    const nextIndex = (currentIndex + 1) % filteredImages?.length;
    setSelectedImage(filteredImages?.[nextIndex]);
  };

  const prevImage = () => {
    const currentIndex = filteredImages?.findIndex(img => img?.id === selectedImage?.id);
    const prevIndex = (currentIndex - 1 + filteredImages?.length) % filteredImages?.length;
    setSelectedImage(filteredImages?.[prevIndex]);
  };

  return (
    <section className="py-16 lg:py-24 bg-background">
      <div className="max-w-7xl mx-auto px-4 lg:px-6">
        <div className="text-center mb-12">
          <h2 className="font-heading font-bold text-3xl lg:text-4xl text-foreground mb-4">
            School Action
          </h2>
          <p className="font-body text-lg text-muted-foreground max-w-2xl mx-auto">
            Capturing moments of impact, growth, and connection
          </p>
        </div>
        
        {/* Category Filter */}
        <div className="flex flex-wrap justify-center gap-3 mb-12">
          {categories?.map((category) => (
            <button
              key={category}
              onClick={() => setActiveCategory(category)}
              className={`px-4 py-2 rounded-full font-body font-medium transition-smooth ${
                activeCategory === category
                  ? 'bg-primary text-primary-foreground'
                  : 'bg-muted text-muted-foreground hover:bg-primary/10 hover:text-primary'
              }`}
            >
              {category}
            </button>
          ))}
        </div>
        
        {/* Gallery Grid */}
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
          {filteredImages?.map((image) => (
            <div
              key={image?.id}
              className="group relative overflow-hidden rounded-xl shadow-card hover:shadow-elevated transition-smooth cursor-pointer hover-lift"
              onClick={() => openModal(image)}
            >
              <div className="relative overflow-hidden h-64">
                <Image
                  src={image?.src}
                  alt={image?.alt}
                  className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                />
                <div className="absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-colors duration-300"></div>
                
                {/* Overlay */}
                <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                  <div className="absolute bottom-0 left-0 right-0 p-4">
                    <div className="flex items-center justify-between">
                      <div>
                        <p className="font-body font-medium text-white text-sm mb-1">
                          {image?.title}
                        </p>
                        <span className="inline-block bg-primary/80 text-primary-foreground px-2 py-1 rounded text-xs font-medium">
                          {image?.category}
                        </span>
                      </div>
                      <Icon name="ZoomIn" size={20} className="text-white" />
                    </div>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
        
        {/* Modal */}
        {selectedImage && (
          <div className="fixed inset-0 z-50 bg-black/80 flex items-center justify-center p-4">
            <div className="relative max-w-4xl w-full max-h-[90vh] bg-card rounded-xl overflow-hidden">
              {/* Close Button */}
              <button
                onClick={closeModal}
                className="absolute top-4 right-4 z-10 w-10 h-10 bg-black/50 hover:bg-black/70 text-white rounded-full flex items-center justify-center transition-smooth"
              >
                <Icon name="X" size={20} />
              </button>
              
              {/* Navigation Buttons */}
              <button
                onClick={prevImage}
                className="absolute left-4 top-1/2 transform -translate-y-1/2 z-10 w-10 h-10 bg-black/50 hover:bg-black/70 text-white rounded-full flex items-center justify-center transition-smooth"
              >
                <Icon name="ChevronLeft" size={20} />
              </button>
              
              <button
                onClick={nextImage}
                className="absolute right-4 top-1/2 transform -translate-y-1/2 z-10 w-10 h-10 bg-black/50 hover:bg-black/70 text-white rounded-full flex items-center justify-center transition-smooth"
              >
                <Icon name="ChevronRight" size={20} />
              </button>
              
              {/* Image */}
              <div className="relative">
                <Image
                  src={selectedImage?.src}
                  alt={selectedImage?.alt}
                  className="w-full h-auto max-h-[70vh] object-contain"
                />
              </div>
              
              {/* Image Info */}
              <div className="p-6">
                <div className="flex items-start justify-between">
                  <div>
                    <h3 className="font-heading font-semibold text-xl text-foreground mb-2">
                      {selectedImage?.title}
                    </h3>
                    <p className="font-body text-muted-foreground mb-3">
                      {selectedImage?.description}
                    </p>
                    <span className="inline-block bg-primary/10 text-primary px-3 py-1 rounded-full text-sm font-medium">
                      {selectedImage?.category}
                    </span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </section>
  );
};

export default PhotoGallery;