import React, { useState } from "react";

import Icon from "../../components/AppIcon";
import Image from "../../components/AppImage";
import { Helmet } from "react-helmet";
import PublicHeader from "../../components/ui/PublicHeader";
import Footer from "../../components/ui/Footer";
import DocumentViewer from "../../components/DocumentViewer";

const Documents = () => {
  const [viewerOpen, setViewerOpen] = useState(false);
  const [viewerUrl, setViewerUrl] = useState("");
  const [viewerName, setViewerName] = useState("");
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedCategory, setSelectedCategory] = useState("all");
  const [sortBy, setSortBy] = useState("name");

  // Document categories
  const categories = [
    { id: "all", name: "All Documents", icon: "FileText" },
    { id: "academic", name: "Academic", icon: "BookOpen" },
    { id: "administrative", name: "Administrative", icon: "ClipboardList" },
    { id: "policies", name: "Policies", icon: "Shield" },
    { id: "forms", name: "Forms", icon: "FileEdit" },
  {
    id: 7,
    name: "School Policy Example",
    category: "administrative",
    description: "Example PDF for school policy, update with your real file names as needed.",
    fileSize: "2.1 MB",
    fileType: "PDF",
    uploadDate: "2025-09-01",
    downloads: 78,
    icon: "Users",
    url: "/assets/library/html.pdf",
  },
    // 	downloads: 89,
    // 	icon: "Book",
    // 	url: "#",
    // },
    // {
    // 	id: 3,
    // 	name: "Parent Registration Form",
    // 	category: "forms",
    // 	description: "Official form for new parent registration and enrollment",
    // 	fileSize: "1.2 MB",
    // 	fileType: "PDF",
    // 	uploadDate: "2024-01-08",
    // 	downloads: 234,
    // 	icon: "UserPlus",
    // 	url: "#",
    // },
    // {
    // 	id: 4,
    // 	name: "Monthly Newsletter - January 2024",
    // 	category: "newsletters",
    // 	description: "Latest school news, achievements, and upcoming events",
    // 	fileSize: "3.1 MB",
    // 	fileType: "PDF",
    // 	uploadDate: "2024-01-05",
    // 	downloads: 67,
    // 	icon: "Mail",
    // 	url: "#",
    // },
    // {
    // 	id: 5,
    // 	name: "Academic Performance Report Template",
    // 	category: "academic",
    // 	description: "Template for generating student academic performance reports",
    // 	fileSize: "1.8 MB",
    // 	fileType: "DOCX",
    // 	uploadDate: "2024-01-03",
    // 	downloads: 45,
    // 	icon: "BarChart3",
    // 	url: "#",
    // },
    // {
    // 	id: 6,
    // 	name: "School Safety Policy",
    // 	category: "policies",
    // 	description: "Comprehensive safety guidelines and emergency procedures",
    // 	fileSize: "4.2 MB",
    // 	fileType: "PDF",
    // 	uploadDate: "2023-12-28",
    // 	downloads: 123,
    // 	icon: "Shield",
    // 	url: "#",
    // },
    {
      id: 7,
      name: "SchoolFees Structure 2025-2026 NESA",
      category: "administrative",
      description:
        "Detailed breakdown of tuition fees, payment schedules, and financial policies f",
      fileSize: "2.1 MB",
      fileType: "PDF",
      uploadDate: "2025-09-01",
      downloads: 78,
      icon: "Users",
      url: "../../../assets/documents/Schoolfees Nesa 2025-2026.pdf",
    },
    {
      id: 8,
      name: "SchoolFees Structure 2025-2026 Private",
      category: "administrative",
      description:
        "Detailed breakdown of tuition fees, payment schedules, and financial policies",
      fileSize: "2.1 MB",
      fileType: "PDF",
      uploadDate: "2025-09-01",
      downloads: 8,
      icon: "Users",
      url: "../../../assets/documents/schoolfees Prive 2025-2026.pdf",
    },
    // {
    // 	id: 8,
    // 	name: "Library Resource Guide",
    // 	category: "academic",
    // 	description: "Guide to available library resources and borrowing procedures",
    // 	fileSize: "2.7 MB",
    // 	fileType: "PDF",
    // 	uploadDate: "2023-12-15",
    // 	downloads: 92,
    // 	icon: "Library",
    // 	url: "#",
    // },
  ];

  // Filter documents based on search and category
  const filteredDocuments = documents.filter((doc) => {
    const matchesSearch =
      doc.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      doc.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory =
      selectedCategory === "all" || doc.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  // Sort documents
  const sortedDocuments = [...filteredDocuments].sort((a, b) => {
    switch (sortBy) {
      case "name":
        return a.name.localeCompare(b.name);
      case "date":
        return new Date(b.uploadDate) - new Date(a.uploadDate);
      case "downloads":
        return b.downloads - a.downloads;
      case "size":
        return parseFloat(a.fileSize) - parseFloat(b.fileSize);
      default:
        return 0;
    }
  });

  const getPublicUrl = (url) => {
    if (url.startsWith("/")) return url;
    return "/assets/documents/" + url.split("/").pop();
  };

  const handleView = (document) => {
    setViewerUrl(getPublicUrl(document.url));
    setViewerName(document.name);
    setViewerOpen(true);
  };



  const handleDownload = (document) => {
    let url = getPublicUrl(document.url);
    let filename = document.name;
    if (!filename.toLowerCase().endsWith(".pdf")) {
      filename += ".pdf";
    }
    const link = document.createElement("a");
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString("en-US", {
      year: "numeric",
      month: "short",
      day: "numeric",
    });
  };

  return (
    <>
      <Helmet>
        <title>Documents - GS DES PARENTS</title>
        <meta
          name="description"
          content="Access and download important school documents, forms, policies, and resources from GS DES PARENTS."
        />
        <meta
          name="keywords"
          content="documents, forms, policies, academic calendar, handbook, GS DES PARENTS, school resources"
        />
        <meta property="og:title" content="Documents - GS DES PARENTS" />
        <meta
          property="og:description"
          content="Access and download important school documents and resources"
        />
        <meta property="og:type" content="website" />
        <meta name="twitter:card" content="summary_large_image" />
        <link rel="canonical" href="/documents" />
      </Helmet>

      <div className="min-h-screen bg-background">
        {/* Header */}
        <PublicHeader />

        {/* Main Content */}
        <main className="pt-16">
          {/* Hero Section */}
          <section className="py-16 lg:py-20 bg-gradient-to-br from-primary/5 to-secondary/5">
            <div className="max-w-7xl mx-auto px-4 lg:px-6">
              <div className="text-center mb-12">
                <h1 className="font-heading font-bold text-4xl lg:text-5xl text-foreground mb-4">
                  School Documents
                </h1>
                <p className="font-body text-lg text-muted-foreground max-w-3xl mx-auto">
                  Access and download important school documents, forms,
                  policies, and resources. All documents are organized by
                  category for easy navigation.
                </p>
              </div>

              {/* Search and Filter Bar */}
              <div className="max-w-4xl mx-auto">
                <div className="bg-card border border-border rounded-2xl p-6 shadow-card">
                  <div className="flex flex-col lg:flex-row gap-4">
                    {/* Search Input */}
                    <div className="flex-1">
                      <div className="relative">
                        <Icon
                          name="Search"
                          size={20}
                          className="absolute left-3 top-1/2 transform -translate-y-1/2 text-muted-foreground"
                        />
                        <input
                          type="text"
                          placeholder="Search documents..."
                          value={searchTerm}
                          onChange={(e) => setSearchTerm(e.target.value)}
                          className="w-full pl-10 pr-4 py-3 bg-background border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-primary focus:border-transparent"
                        />
                      </div>
                    </div>

                    {/* Category Filter */}
                    <div className="lg:w-48">
                      <select
                        value={selectedCategory}
                        onChange={(e) => setSelectedCategory(e.target.value)}
                        className="w-full px-4 py-3 bg-background border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-primary focus:border-transparent"
                      >
                        {categories.map((category) => (
                          <option key={category.id} value={category.id}>
                            {category.name}
                          </option>
                        ))}
                      </select>
                    </div>

                    {/* Sort Options */}
                    <div className="lg:w-40">
                      <select
                        value={sortBy}
                        onChange={(e) => setSortBy(e.target.value)}
                        className="w-full px-4 py-3 bg-background border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-primary focus:border-transparent"
                      >
                        <option value="name">Sort by Name</option>
                        <option value="date">Sort by Date</option>
                        <option value="downloads">Sort by Downloads</option>
                        <option value="size">Sort by Size</option>
                      </select>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </section>

          {/* Documents Grid */}
          <section className="py-16 lg:py-20">
            <div className="max-w-7xl mx-auto px-4 lg:px-6">
              {/* Results Summary */}
              <div className="flex items-center justify-between mb-8">
                <div className="flex items-center space-x-4">
                  <h2 className="font-heading font-semibold text-2xl text-foreground">
                    Documents ({sortedDocuments.length})
                  </h2>
                  {selectedCategory !== "all" && (
                    <span className="px-3 py-1 bg-primary/10 text-primary rounded-full text-sm font-medium">
                      {
                        categories.find((cat) => cat.id === selectedCategory)
                          ?.name
                      }
                    </span>
                  )}
                </div>
                <div className="text-sm text-muted-foreground">
                  Showing {sortedDocuments.length} of {documents.length}{" "}
                  documents
                </div>
              </div>

              {/* Documents Grid */}
              <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
                {sortedDocuments.map((document) => (
                  <div
                    key={document.id}
                    className="bg-card border border-border rounded-2xl p-6 shadow-card hover:shadow-elevated transition-smooth hover-lift"
                  >
                    {/* Document Header */}
                    <div className="flex items-start justify-between mb-4">
                      <div className="flex items-center space-x-3">
                        <div className="w-12 h-12 bg-primary/10 rounded-xl flex items-center justify-center">
                          <Icon
                            name={document.icon}
                            size={24}
                            className="text-primary"
                          />
                        </div>
                        <div>
                          <h3 className="font-heading font-semibold text-lg text-foreground line-clamp-2">
                            {document.name}
                          </h3>
                          <p className="text-sm text-muted-foreground">
                            {
                              categories.find(
                                (cat) => cat.id === document.category
                              )?.name
                            }
                          </p>
                        </div>
                      </div>
                      <div className="flex items-center space-x-1 text-xs text-muted-foreground">
                        <Icon name="Download" size={14} />
                        <span>{document.downloads}</span>
                      </div>
                    </div>

                    {/* Document Description */}
                    <p className="text-sm text-muted-foreground mb-4 line-clamp-3">
                      {document.description}
                    </p>

                    {/* Document Meta */}
                    <div className="flex items-center justify-between text-xs text-muted-foreground mb-4">
                      <div className="flex items-center space-x-4">
                        <span className="flex items-center space-x-1">
                          <Icon name="File" size={12} />
                          <span>{document.fileType}</span>
                        </span>
                        <span className="flex items-center space-x-1">
                          <Icon name="HardDrive" size={12} />
                          <span>{document.fileSize}</span>
                        </span>
                      </div>
                      <span>{formatDate(document.uploadDate)}</span>
                    </div>

                    {/* View and Download Buttons */}
                    <div className="flex gap-2">
                      <button
                        onClick={() => handleView(document)}
                        className="flex-1 bg-blue-600 text-white py-3 px-4 rounded-lg font-medium hover:bg-blue-700 transition-colors flex items-center justify-center space-x-2 text-center"
                      >
                        <Icon name="Eye" size={16} />
                        <span>View</span>
                      </button>
                      <button
                        onClick={() => handleDownload(document)}
                        className="flex-1 bg-primary text-primary-foreground py-3 px-4 rounded-lg font-medium hover:bg-primary/90 transition-smooth flex items-center justify-center space-x-2"
                      >
                        <Icon name="Download" size={16} />
                        <span>Download</span>
                      </button>
                    </div>
                  </div>
                ))}
              </div>

              {/* Empty State */}
              {sortedDocuments.length === 0 && (
                <div className="text-center py-16">
                  <div className="w-24 h-24 bg-muted rounded-full flex items-center justify-center mx-auto mb-6">
                    <Icon
                      name="FileX"
                      size={48}
                      className="text-muted-foreground"
                    />
                  </div>
                  <h3 className="font-heading font-semibold text-xl text-foreground mb-2">
                    No documents found
                  </h3>
                  <p className="text-muted-foreground">
                    Try adjusting your search terms or category filter
                  </p>
                </div>
              )}
            </div>
          </section>

          {/* Quick Access Section */}
          <section className="py-16 lg:py-20 bg-muted/30">
            <div className="max-w-7xl mx-auto px-4 lg:px-6">
              <div className="text-center mb-12">
                <h2 className="font-heading font-bold text-3xl lg:text-4xl text-foreground mb-4">
                  Quick Access
                </h2>
                <p className="font-body text-lg text-muted-foreground max-w-2xl mx-auto">
                  Frequently accessed documents and resources
                </p>
              </div>

              <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-4">
                {categories.slice(1).map((category) => (
                  <div
                    key={category.id}
                    onClick={() => setSelectedCategory(category.id)}
                    className="bg-card border border-border rounded-2xl p-6 text-center hover:shadow-elevated transition-smooth hover-lift cursor-pointer"
                  >
                    <div className="w-16 h-16 bg-primary/10 rounded-2xl flex items-center justify-center mx-auto mb-4">
                      <Icon
                        name={category.icon}
                        size={32}
                        className="text-primary"
                      />
                    </div>
                    <h3 className="font-heading font-semibold text-lg text-foreground mb-2">
                      {category.name}
                    </h3>
                    <p className="text-sm text-muted-foreground">
                      {
                        documents.filter((doc) => doc.category === category.id)
                          .length
                      }{" "}
                      documents
                    </p>
                  </div>
                ))}
              </div>
            </div>
          </section>
        </main>
        {/* Document Viewer Modal */}
        <DocumentViewer
          url={viewerOpen ? viewerUrl : ""}
          name={viewerName}
          onClose={() => setViewerOpen(false)}
        />

        {/* Footer */}
        <Footer />
      </div>
    </>
  );
};

export default Documents;
