import React, { useState } from 'react';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import { Checkbox } from '../../../components/ui/Checkbox';
import Select from '../../../components/ui/Select';

const PreferencesTab = ({ userPreferences, onUpdatePreferences }) => {
  const [preferences, setPreferences] = useState({
    notifications: {
      email: userPreferences?.notifications?.email || true,
      push: userPreferences?.notifications?.push || true,
      sms: userPreferences?.notifications?.sms || false,
      eventReminders: userPreferences?.notifications?.eventReminders || true,
      announcements: userPreferences?.notifications?.announcements || true,
      blogUpdates: userPreferences?.notifications?.blogUpdates || false,
      membershipUpdates: userPreferences?.notifications?.membershipUpdates || true
    },
    privacy: {
      profileVisibility: userPreferences?.privacy?.profileVisibility || 'members',
      showEmail: userPreferences?.privacy?.showEmail || false,
      showPhone: userPreferences?.privacy?.showPhone || false,
      allowDirectMessages: userPreferences?.privacy?.allowDirectMessages || true,
      showOnlineStatus: userPreferences?.privacy?.showOnlineStatus || true
    },
    communication: {
      language: userPreferences?.communication?.language || 'en',
      timezone: userPreferences?.communication?.timezone || 'Africa/Kigali',
      emailFrequency: userPreferences?.communication?.emailFrequency || 'weekly',
      preferredContactMethod: userPreferences?.communication?.preferredContactMethod || 'email'
    },
    content: {
      autoPlayVideos: userPreferences?.content?.autoPlayVideos || false,
      showImages: userPreferences?.content?.showImages || true,
      compactView: userPreferences?.content?.compactView || false,
      darkMode: userPreferences?.content?.darkMode || false
    }
  });

  const [hasChanges, setHasChanges] = useState(false);

  const languageOptions = [
    { value: 'en', label: 'English' },
    { value: 'rw', label: 'Kinyarwanda' },
    { value: 'fr', label: 'Français' }
  ];

  const timezoneOptions = [
    { value: 'Africa/Kigali', label: 'Kigali (CAT)' },
    { value: 'UTC', label: 'UTC' },
    { value: 'Europe/London', label: 'London (GMT)' },
    { value: 'America/New_York', label: 'New York (EST)' }
  ];

  const emailFrequencyOptions = [
    { value: 'immediate', label: 'Immediate' },
    { value: 'daily', label: 'Daily Digest' },
    { value: 'weekly', label: 'Weekly Summary' },
    { value: 'monthly', label: 'Monthly Newsletter' },
    { value: 'never', label: 'Never' }
  ];

  const contactMethodOptions = [
    { value: 'email', label: 'Email' },
    { value: 'phone', label: 'Phone' },
    { value: 'whatsapp', label: 'WhatsApp' },
    { value: 'in-app', label: 'In-App Notifications' }
  ];

  const profileVisibilityOptions = [
    { value: 'public', label: 'Public (Everyone)' },
    { value: 'members', label: 'Members Only' },
    { value: 'private', label: 'Private (Only Me)' }
  ];

  const handleNotificationChange = (key, checked) => {
    setPreferences(prev => ({
      ...prev,
      notifications: {
        ...prev?.notifications,
        [key]: checked
      }
    }));
    setHasChanges(true);
  };

  const handlePrivacyChange = (key, value) => {
    setPreferences(prev => ({
      ...prev,
      privacy: {
        ...prev?.privacy,
        [key]: value
      }
    }));
    setHasChanges(true);
  };

  const handleCommunicationChange = (key, value) => {
    setPreferences(prev => ({
      ...prev,
      communication: {
        ...prev?.communication,
        [key]: value
      }
    }));
    setHasChanges(true);
  };

  const handleContentChange = (key, value) => {
    setPreferences(prev => ({
      ...prev,
      content: {
        ...prev?.content,
        [key]: value
      }
    }));
    setHasChanges(true);
  };

  const handleSavePreferences = () => {
    onUpdatePreferences(preferences);
    setHasChanges(false);
  };

  const handleResetPreferences = () => {
    setPreferences({
      notifications: {
        email: userPreferences?.notifications?.email || true,
        push: userPreferences?.notifications?.push || true,
        sms: userPreferences?.notifications?.sms || false,
        eventReminders: userPreferences?.notifications?.eventReminders || true,
        announcements: userPreferences?.notifications?.announcements || true,
        blogUpdates: userPreferences?.notifications?.blogUpdates || false,
        membershipUpdates: userPreferences?.notifications?.membershipUpdates || true
      },
      privacy: {
        profileVisibility: userPreferences?.privacy?.profileVisibility || 'members',
        showEmail: userPreferences?.privacy?.showEmail || false,
        showPhone: userPreferences?.privacy?.showPhone || false,
        allowDirectMessages: userPreferences?.privacy?.allowDirectMessages || true,
        showOnlineStatus: userPreferences?.privacy?.showOnlineStatus || true
      },
      communication: {
        language: userPreferences?.communication?.language || 'en',
        timezone: userPreferences?.communication?.timezone || 'Africa/Kigali',
        emailFrequency: userPreferences?.communication?.emailFrequency || 'weekly',
        preferredContactMethod: userPreferences?.communication?.preferredContactMethod || 'email'
      },
      content: {
        autoPlayVideos: userPreferences?.content?.autoPlayVideos || false,
        showImages: userPreferences?.content?.showImages || true,
        compactView: userPreferences?.content?.compactView || false,
        darkMode: userPreferences?.content?.darkMode || false
      }
    });
    setHasChanges(false);
  };

  return (
    <div className="space-y-8">
      {/* Notification Preferences */}
      <div className="bg-card border border-border rounded-lg p-6">
        <div className="flex items-center space-x-3 mb-6">
          <Icon name="Bell" size={24} className="text-primary" />
          <h3 className="font-heading font-semibold text-lg text-foreground">
            Notification Preferences
          </h3>
        </div>

        <div className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <Checkbox
              label="Email Notifications"
              description="Receive notifications via email"
              checked={preferences?.notifications?.email}
              onChange={(e) => handleNotificationChange('email', e?.target?.checked)}
            />
            <Checkbox
              label="Push Notifications"
              description="Browser and mobile push notifications"
              checked={preferences?.notifications?.push}
              onChange={(e) => handleNotificationChange('push', e?.target?.checked)}
            />
            <Checkbox
              label="SMS Notifications"
              description="Text message notifications"
              checked={preferences?.notifications?.sms}
              onChange={(e) => handleNotificationChange('sms', e?.target?.checked)}
            />
            <Checkbox
              label="Event Reminders"
              description="Reminders for upcoming events"
              checked={preferences?.notifications?.eventReminders}
              onChange={(e) => handleNotificationChange('eventReminders', e?.target?.checked)}
            />
            <Checkbox
              label="Announcements"
              description="Important community announcements"
              checked={preferences?.notifications?.announcements}
              onChange={(e) => handleNotificationChange('announcements', e?.target?.checked)}
            />
            <Checkbox
              label="Blog Updates"
              description="New blog posts and articles"
              checked={preferences?.notifications?.blogUpdates}
              onChange={(e) => handleNotificationChange('blogUpdates', e?.target?.checked)}
            />
          </div>
        </div>
      </div>
      {/* Privacy Settings */}
      <div className="bg-card border border-border rounded-lg p-6">
        <div className="flex items-center space-x-3 mb-6">
          <Icon name="Shield" size={24} className="text-primary" />
          <h3 className="font-heading font-semibold text-lg text-foreground">
            Privacy Settings
          </h3>
        </div>

        <div className="space-y-6">
          <Select
            label="Profile Visibility"
            description="Who can see your profile information"
            options={profileVisibilityOptions}
            value={preferences?.privacy?.profileVisibility}
            onChange={(value) => handlePrivacyChange('profileVisibility', value)}
          />

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <Checkbox
              label="Show Email Address"
              description="Display email on your profile"
              checked={preferences?.privacy?.showEmail}
              onChange={(e) => handlePrivacyChange('showEmail', e?.target?.checked)}
            />
            <Checkbox
              label="Show Phone Number"
              description="Display phone on your profile"
              checked={preferences?.privacy?.showPhone}
              onChange={(e) => handlePrivacyChange('showPhone', e?.target?.checked)}
            />
            <Checkbox
              label="Allow Direct Messages"
              description="Let other members message you"
              checked={preferences?.privacy?.allowDirectMessages}
              onChange={(e) => handlePrivacyChange('allowDirectMessages', e?.target?.checked)}
            />
            <Checkbox
              label="Show Online Status"
              description="Display when you're online"
              checked={preferences?.privacy?.showOnlineStatus}
              onChange={(e) => handlePrivacyChange('showOnlineStatus', e?.target?.checked)}
            />
          </div>
        </div>
      </div>
      {/* Communication Preferences */}
      <div className="bg-card border border-border rounded-lg p-6">
        <div className="flex items-center space-x-3 mb-6">
          <Icon name="MessageSquare" size={24} className="text-primary" />
          <h3 className="font-heading font-semibold text-lg text-foreground">
            Communication Preferences
          </h3>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <Select
            label="Language"
            description="Your preferred language"
            options={languageOptions}
            value={preferences?.communication?.language}
            onChange={(value) => handleCommunicationChange('language', value)}
          />

          <Select
            label="Timezone"
            description="Your local timezone"
            options={timezoneOptions}
            value={preferences?.communication?.timezone}
            onChange={(value) => handleCommunicationChange('timezone', value)}
          />

          <Select
            label="Email Frequency"
            description="How often you receive emails"
            options={emailFrequencyOptions}
            value={preferences?.communication?.emailFrequency}
            onChange={(value) => handleCommunicationChange('emailFrequency', value)}
          />

          <Select
            label="Preferred Contact Method"
            description="How we should contact you"
            options={contactMethodOptions}
            value={preferences?.communication?.preferredContactMethod}
            onChange={(value) => handleCommunicationChange('preferredContactMethod', value)}
          />
        </div>
      </div>
      {/* Content Preferences */}
      <div className="bg-card border border-border rounded-lg p-6">
        <div className="flex items-center space-x-3 mb-6">
          <Icon name="Settings" size={24} className="text-primary" />
          <h3 className="font-heading font-semibold text-lg text-foreground">
            Content Preferences
          </h3>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <Checkbox
            label="Auto-play Videos"
            description="Automatically play videos when scrolling"
            checked={preferences?.content?.autoPlayVideos}
            onChange={(e) => handleContentChange('autoPlayVideos', e?.target?.checked)}
          />
          <Checkbox
            label="Show Images"
            description="Display images in posts and articles"
            checked={preferences?.content?.showImages}
            onChange={(e) => handleContentChange('showImages', e?.target?.checked)}
          />
          <Checkbox
            label="Compact View"
            description="Use compact layout for lists"
            checked={preferences?.content?.compactView}
            onChange={(e) => handleContentChange('compactView', e?.target?.checked)}
          />
          <Checkbox
            label="Dark Mode"
            description="Use dark theme (coming soon)"
            checked={preferences?.content?.darkMode}
            onChange={(e) => handleContentChange('darkMode', e?.target?.checked)}
            disabled
          />
        </div>
      </div>
      {/* Save Actions */}
      {hasChanges && (
        <div className="bg-accent/10 border border-accent/20 rounded-lg p-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-3">
              <Icon name="AlertCircle" size={20} className="text-accent" />
              <p className="font-body text-sm text-foreground">
                You have unsaved changes to your preferences.
              </p>
            </div>
            <div className="flex space-x-3">
              <Button
                variant="outline"
                size="sm"
                onClick={handleResetPreferences}
              >
                Reset
              </Button>
              <Button
                variant="default"
                size="sm"
                iconName="Save"
                iconPosition="left"
                onClick={handleSavePreferences}
              >
                Save Changes
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default PreferencesTab;