import React from 'react';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';


const SocialShare = ({ post, onShare, onBookmark, isBookmarked }) => {
  const socialPlatforms = [
    { name: 'twitter', label: 'Twitter', icon: 'Twitter', color: 'hover:text-blue-500' },
    { name: 'facebook', label: 'Facebook', icon: 'Facebook', color: 'hover:text-blue-600' },
    { name: 'linkedin', label: 'LinkedIn', icon: 'Linkedin', color: 'hover:text-blue-700' }
  ];

  const copyLink = async () => {
    try {
      const url = `${window?.location?.origin}/blog-post-view?slug=${post?.slug}`;
      await navigator?.clipboard?.writeText(url);
      alert('Link copied to clipboard!');
    } catch (err) {
      console.error('Failed to copy link:', err);
    }
  };

  return (
    <div className="bg-card rounded-lg border border-border shadow-card p-6 mb-6">
      <h3 className="font-heading font-bold text-lg text-foreground mb-4 flex items-center">
        <Icon name="Share2" size={20} className="mr-2 text-primary" />
        Share Article
      </h3>
      
      <div className="space-y-3">
        {/* Social Platforms */}
        <div className="grid grid-cols-3 gap-2">
          {socialPlatforms?.map((platform) => (
            <Button
              key={platform?.name}
              variant="outline"
              size="sm"
              onClick={() => onShare?.(platform?.name)}
              className={`flex flex-col items-center p-3 h-auto ${platform?.color}`}
            >
              <Icon name={platform?.icon} size={20} className="mb-1" />
              <span className="text-xs">{platform?.label}</span>
            </Button>
          ))}
        </div>

        {/* Additional Actions */}
        <div className=" pt-3 border-t border-border col-span-3 flex space-x-2 ">
          <Button
            variant="outline"
            size="sm"
            onClick={copyLink}
            fullWidth
            className="justify-start"
          >
            <Icon name="Link" size={16} className="mr-2" />
            Copy Link
          </Button>
          
          <Button
            variant={isBookmarked ? 'default' : 'outline'}
            size="sm"
            onClick={() => onBookmark?.()}
            fullWidth
            className="justify-end"
          >
            <Icon name={isBookmarked ? 'BookmarkCheck' : 'Bookmark'} size={16} className="mr-2" />
            {isBookmarked ? 'Bookmarked' : 'Bookmark'}
          </Button>
        </div>
      </div>
    </div>
  );
};

const ArticleStats = ({ post }) => {
  const stats = [
    { label: 'Views', value: post?.views?.toLocaleString(), icon: 'Eye' },
    { label: 'Shares', value: post?.shares, icon: 'Share2' },
    { label: 'Likes', value: post?.likes, icon: 'Heart' },
    { label: 'Comments', value: '12', icon: 'MessageCircle' }
  ];

  return (
    <div className="bg-card rounded-lg border border-border shadow-card p-6 mb-6">
      <h3 className="font-heading font-bold text-lg text-foreground mb-4 flex items-center">
        <Icon name="BarChart3" size={20} className="mr-2 text-primary" />
        Article Stats
      </h3>
      
      <div className="grid grid-cols-2 gap-4">
        {stats?.map((stat, index) => (
          <div key={index} className="text-center">
            <div className="flex items-center justify-center w-10 h-10 bg-primary/10 rounded-lg mx-auto mb-2">
              <Icon name={stat?.icon} size={18} className="text-primary" />
            </div>
            <div className="font-heading font-bold text-lg text-foreground">
              {stat?.value}
            </div>
            <div className="font-body text-sm text-muted-foreground">
              {stat?.label}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};


const ArticleSidebar = ({ 
  post, 
  onShare, 
  onBookmark, 
  isBookmarked 
}) => {
  return (
    <div className="space-y-6">
      
      <SocialShare 
        post={post}
        onShare={onShare}
        onBookmark={onBookmark}
        isBookmarked={isBookmarked}
      />
      
      <ArticleStats post={post} />
      
    </div>
  );
};

export default ArticleSidebar;