import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Button from '../../../components/ui/Button';
import Input from '../../../components/ui/Input';
import { Checkbox } from '../../../components/ui/Checkbox';
import Icon from '../../../components/AppIcon';

const LoginForm = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    email: '',
    password: '',
    rememberMe: false
  });
  const [errors, setErrors] = useState({});
  const [isLoading, setIsLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  // Mock credentials for authentication
  const mockCredentials = [
    { email: 'admin@unmute.rw', password: 'admin123', role: 'admin' },
    { email: 'member@unmute.rw', password: 'member123', role: 'member' },
    { email: 'john.doe@unmute.rw', password: 'password123', role: 'member' }
  ];

  const validateForm = () => {
    const newErrors = {};

    if (!formData?.email) {
      newErrors.email = 'Email is required';
    } else if (!/\S+@\S+\.\S+/?.test(formData?.email)) {
      newErrors.email = 'Please enter a valid email address';
    }

    if (!formData?.password) {
      newErrors.password = 'Password is required';
    } else if (formData?.password?.length < 6) {
      newErrors.password = 'Password must be at least 6 characters';
    }

    setErrors(newErrors);
    return Object.keys(newErrors)?.length === 0;
  };

  const handleInputChange = (e) => {
    const { name, value, type, checked } = e?.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));

    // Clear error when user starts typing
    if (errors?.[name]) {
      setErrors(prev => ({
        ...prev,
        [name]: ''
      }));
    }
  };

  const handleSubmit = async (e) => {
    e?.preventDefault();
    
    if (!validateForm()) return;

    setIsLoading(true);

    try {
      // Simulate API call delay
      await new Promise(resolve => setTimeout(resolve, 1500));

      // Check credentials
      const user = mockCredentials?.find(
        cred => cred?.email === formData?.email && cred?.password === formData?.password
      );

      if (user) {
        // Store user session (in real app, this would be handled by auth service)
        localStorage.setItem('user', JSON.stringify({
          email: user?.email,
          role: user?.role,
          name: user?.email?.split('@')?.[0]?.replace('.', ' ')?.replace(/\b\w/g, l => l?.toUpperCase()),
          avatar: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150&h=150&fit=crop&crop=face'
        }));

        // Redirect based on role
        if (user?.role === 'admin') {
          navigate('/admin-panel');
        } else {
          navigate('/admin-panel');
        }
      } else {
        setErrors({
          submit: 'Invalid email or password. Please check your credentials and try again.'
        });
      }
    } catch (error) {
      setErrors({
        submit: 'Login failed. Please try again later.'
      });
    } finally {
      setIsLoading(false);
    }
  };


  const togglePasswordVisibility = () => {
    setShowPassword(!showPassword);
  };

  return (
    <div className="w-full max-w-md mx-auto">
      <div className="bg-card rounded-lg shadow-elevated p-8">
        {/* Header */}
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-primary rounded-full flex items-center justify-center mx-auto mb-4">
            <Icon name="Users" size={32} className="text-primary-foreground" />
          </div>
          <h1 className="font-heading font-bold text-2xl text-foreground mb-2">
            Welcome Back
          </h1>
        </div>

        {/* Login Form */}
        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Email Input */}
          <Input
            label="Email Address"
            type="email"
            name="email"
            placeholder="Enter your email"
            value={formData?.email}
            onChange={handleInputChange}
            error={errors?.email}
            required
            autoComplete="email"
          />

          {/* Password Input */}
          <div className="relative">
            <Input
              label="Password"
              type={showPassword ? 'text' : 'password'}
              name="password"
              placeholder="Enter your password"
              value={formData?.password}
              onChange={handleInputChange}
              error={errors?.password}
              required
              autoComplete="current-password"
            />
            <button
              type="button"
              onClick={togglePasswordVisibility}
              className="absolute right-3 top-9 text-muted-foreground hover:text-foreground transition-smooth"
              aria-label={showPassword ? 'Hide password' : 'Show password'}
            >
              <Icon name={showPassword ? 'EyeOff' : 'Eye'} size={20} />
            </button>
          </div>

          {/* Remember Me & Forgot Password */}
          <div className="flex items-center justify-between">
            <Checkbox
              label="Remember me"
              name="rememberMe"
              checked={formData?.rememberMe}
              onChange={handleInputChange}
            />
            <button
              type="button"
              className="font-body text-sm text-primary hover:text-primary/80 transition-smooth"
              onClick={() => {
                // In real app, this would open forgot password modal/page
                alert('Forgot password functionality would be implemented here');
              }}
            >
              Forgot password?
            </button>
          </div>

          {/* Submit Error */}
          {errors?.submit && (
            <div className="bg-error/10 border border-error/20 rounded-md p-3">
              <div className="flex items-center space-x-2">
                <Icon name="AlertCircle" size={16} className="text-error" />
                <p className="font-body text-sm text-error">{errors?.submit}</p>
              </div>
            </div>
          )}

          {/* Login Button */}
          <Button
            type="submit"
            variant="default"
            fullWidth
            loading={isLoading}
            disabled={isLoading}
            iconName="LogIn"
            iconPosition="left"
            
          >
            {isLoading ? 'Signing In...' : 'Sign In'}
          </Button>
        
        </form>

        {/* Register Link */}
        <div className="mt-8 text-center">
          <p className="font-body text-sm text-muted-foreground">
            Powered by <span className="font-semibold text-blue-700">
          <a href="https://gnintellex.netlify.app/"> GNA IntelleX</a></span>
          </p>
        </div>
      </div>
      {/* Mock Credentials Info */}
      <div className="mt-6 bg-muted/50 rounded-lg p-4">
        <h3 className="font-body font-medium text-sm text-foreground mb-2 flex items-center">
          <Icon name="Info" size={16} className="mr-2 text-primary" />
          Demo Credentials
        </h3>
        <div className="space-y-2 text-xs font-mono">
          <div>
            <span className="text-muted-foreground">Admin:</span>
            <span className="ml-2 text-foreground">admin@unmute.rw / admin123</span>
          </div>
          <div>
            <span className="text-muted-foreground">Member:</span>
            <span className="ml-2 text-foreground">member@unmute.rw / member123</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LoginForm;